1	//! Blocking HTTP download for `http-zip` recipe sources.
2	//!
3	//! Deliberately small next to `esclient`'s retry loop: that one protects an
4	//! interactive indexing session against a live server's 429/503 storms; this
5	//! one fetches a handful of public dump URLs per run. The part worth copying
6	//! is the SHAPE — bounded attempts, exponential backoff, one-line errors that
7	//! name the URL and status, and an atomic tmp+rename write so a partial
8	//! download never exists under the cache's final name.
9	
10	use std::path::Path;
11	use std::time::Duration;
12	
13	use anyhow::{bail, Context, Result};
14	
15	/// Refuse to buffer more than this on disk. Public advisory dumps are
16	/// megabytes-to-a-few-hundred-MB; a runaway URL should fail loudly, not fill
17	/// the disk. Decompression safety is enforced separately at zip-extract time
18	/// (a small zip can expand enormously — see `source::extract_zip`).
19	const MAX_DOWNLOAD_BYTES: u64 = 4 << 30;
20	
21	const ATTEMPTS: u32 = 3;
22	const INITIAL_BACKOFF: Duration = Duration::from_secs(1);
23	
24	/// Download `url` to `dest` (atomically). Returns the byte count.
25	pub fn download(url: &str, dest: &Path) -> Result<u64> {
26	    let client = reqwest::blocking::Client::builder()
27	        .timeout(Duration::from_secs(600))
28	        .connect_timeout(Duration::from_secs(30))
29	        .redirect(reqwest::redirect::Policy::limited(10))
30	        .build()
31	        .context("build http client")?;
32	
33	    let mut last_err = String::new();
34	    for attempt in 0..ATTEMPTS {
35	        if attempt > 0 {
36	            std::thread::sleep(INITIAL_BACKOFF * (1 << (attempt - 1)));
37	        }
38	        match once(&client, url, dest) {
39	            Ok(n) => return Ok(n),
40	            // keep the FIRST error: later attempts against a dead endpoint
41	            // report less (bare connect failure vs "HTTP 404")
42	            Err(e) => {
43	                if last_err.is_empty() {
44	                    last_err = e.to_string();
45	                }
46	            }
47	        }
48	    }
49	    bail!("download {url} failed after {ATTEMPTS} attempts: {last_err}")
50	}
51	
52	fn once(client: &reqwest::blocking::Client, url: &str, dest: &Path) -> Result<u64> {
53	    use std::io::{Read, Write};
54	    let resp = client
55	        .get(url)
56	        .send()
57	        .with_context(|| format!("GET {url}"))?;
58	    let status = resp.status();
59	    if !status.is_success() {
60	        // not retry-worthy in the same way as a timeout, but cheap to retry
61	        // once upstream hiccuped — the loop above bounds it
62	        bail!("HTTP {status} for {url}");
63	    }
64	    if let Some(len) = resp.content_length() {
65	        if len > MAX_DOWNLOAD_BYTES {
66	            bail!("{url} declares {len} bytes, over the {MAX_DOWNLOAD_BYTES} cap");
67	        }
68	    }
69	
70	    let tmp = dest.with_extension("part");
71	    if let Some(parent) = dest.parent() {
72	        std::fs::create_dir_all(parent).with_context(|| format!("create {}", parent.display()))?;
73	    }
74	    let mut file =
75	        std::fs::File::create(&tmp).with_context(|| format!("create {}", tmp.display()))?;
76	    let mut written: u64 = 0;
77	    // stream: `resp.bytes()` would buffer the entire body in memory before
78	    // any cap could fire
79	    let mut reader = resp.take(MAX_DOWNLOAD_BYTES + 1);
80	    let mut buf = vec![0u8; 64 * 1024];
81	    loop {
82	        let n = reader.read(&mut buf)?;
83	        if n == 0 {
84	            break;
85	        }
86	        written += n as u64;
87	        if written > MAX_DOWNLOAD_BYTES {
88	            let _ = std::fs::remove_file(&tmp);
89	            bail!("{url} exceeded the {MAX_DOWNLOAD_BYTES} download cap");
90	        }
91	        file.write_all(&buf[..n])?;
92	    }
93	    file.flush()?;
94	    drop(file);
95	    std::fs::rename(&tmp, dest).with_context(|| format!("move {} into place", tmp.display()))?;
96	    Ok(written)
97	}
