99	#[cfg(test)]
100	mod tests {
101	    use super::*;
102	
103	    /// One canned HTTP response over a raw TcpListener — the fake-node
104	    /// pattern from `failure_resume_http_tests.rs`. No reqwest server dep.
105	    /// Owned arguments: the serving thread must be 'static.
106	    fn serve_once(head: String, body: Vec<u8>) -> std::io::Result<std::net::SocketAddr> {
107	        let listener = std::net::TcpListener::bind("127.0.0.1:0")?;
108	        let addr = listener.local_addr()?;
109	        std::thread::spawn(move || {
110	            if let Ok((mut sock, _)) = listener.accept() {
111	                use std::io::{Read, Write};
112	                let mut buf = [0u8; 1024];
113	                let _ = sock.read(&mut buf); // discard the request
114	                let _ = sock.write_all(head.as_bytes());
115	                let _ = sock.write_all(&body);
116	                let _ = sock.flush();
117	            }
118	        });
119	        Ok(addr)
120	    }
121	
122	    #[test]
123	    fn downloads_and_retries() {
124	        let tmp = tempfile::tempdir().unwrap();
125	        let dest = tmp.path().join("dump.zip");
126	
127	        // success path
128	        let addr = serve_once(
129	            "HTTP/1.1 200 OK\r\nContent-Length: 6\r\nConnection: close\r\n\r\n".to_string(),
130	            b"hello!".to_vec(),
131	        )
132	        .unwrap();
133	        let n = download(&format!("http://{addr}/x.zip"), &dest).unwrap();
134	        assert_eq!(n, 6);
135	        assert_eq!(std::fs::read(&dest).unwrap(), b"hello!");
136	        assert!(
137	            !tmp.path().join("dump.part").exists(),
138	            "no partial left behind"
139	        );
140	
141	        // failure path: 404 on every attempt → named error, no dest file
142	        let addr = serve_once(
143	            "HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".to_string(),
144	            Vec::new(),
145	        )
146	        .unwrap();
147	        let err = download(&format!("http://{addr}/gone.zip"), &dest)
148	            .unwrap_err()
149	            .to_string();
150	        assert!(err.contains("404"), "{err}");
151	        assert!(err.contains("3 attempts"), "{err}");
152	    }
153	}
