1	//! Detached ed25519 signatures over a pack's SHA256SUMS — the publish half
2	//! of the pack format.
3	//!
4	//! Checksums (M1) prove a pack arrived intact; a signature proves WHO built
5	//! it. That distinction is the whole design: SHA256SUMS re-hashing catches
6	//! corruption and lazy tampering, but an attacker who rebuilds a pack
7	//! self-consistently produces valid checksums for malicious records — the
8	//! case `read_manifest`'s tests explicitly left to "a later milestone",
9	//! which is this file. Every prior-art vulnerability database surveyed at
10	//! design time (Trivy DB, Grype/vunnel, PrimeVul) ships unsigned; this is
11	//! the open lane, not table stakes.
12	//!
13	//! The trust model, stated plainly:
14	//!
15	//! - The **public** key travels out of band — committed next to the pack
16	//!   recipe in this repo, and on xerj.org — never inside the pack (a key
17	//!   shipped beside its own signature verifies nothing).
18	//! - The **seed** lives only in CI's secrets; `corpus build` never sees it.
19	//!   Signing is a separate `corpus sign` step so a local build and a
20	//!   published build differ by exactly one file.
21	//! - v1 is a single release key. Rotation is by re-publishing under a new
22	//!   key and updating the two public locations; consumers pin the file they
23	//!   fetched, and the README says so.
24	//!
25	//! Format, deliberately boring: `SHA256SUMS.sig` is the RAW 64-byte ed25519
26	//! signature of SHA256SUMS' exact bytes. No armored envelopes, no trusted
27	//! comments — a consumer with any ed25519 implementation can verify the
28	//! bytes without this crate. The `.sig` file is intentionally absent from
29	//! SHA256SUMS itself (it signs that file; covering it would be circular) —
30	//! `read_manifest` only re-hashes files the SUMS names, so the signature
31	//! rides in a pack dir or zip without breaking older readers.
32	
33	use std::path::{Path, PathBuf};
34	
35	use anyhow::{bail, Context, Result};
36	use ring::rand::SecureRandom;
37	use ring::signature::{Ed25519KeyPair, KeyPair, UnparsedPublicKey};
38	
39	/// The signature file name inside a pack directory.
40	pub const SIG_NAME: &str = "SHA256SUMS.sig";
41	
42	/// Generate a fresh ed25519 keypair as (seed_hex, public_hex) — 32 bytes
43	/// each, lower-case hex. The seed is everything an attacker needs: it goes
44	/// to CI secrets and nowhere else; the public half is published.
45	pub fn generate_keypair() -> Result<(String, String)> {
46	    let mut seed = [0u8; 32];
47	    ring::rand::SystemRandom::new()
48	        .fill(&mut seed)
49	        .map_err(|_| anyhow::anyhow!("key generation failed (no entropy source?)"))?;
50	    let pair = Ed25519KeyPair::from_seed_unchecked(&seed)
51	        .map_err(|_| anyhow::anyhow!("a fresh 32-byte seed is always valid — ring disagrees"))?;
52	    Ok((hex(&seed), hex(pair.public_key().as_ref())))
53	}
54	
55	/// Sign `<pack>/SHA256SUMS` with a seed file, writing `<pack>/SHA256SUMS.sig`.
56	/// Refuses to sign a pack whose SUMS is missing (nothing to sign) and
57	/// overwrites a previous `.sig` — re-signing a rebuilt pack is the normal
58	/// publish step, and a stale signature would fail verification anyway.
59	pub fn sign_pack(pack_dir: &Path, seed_hex: &str) -> Result<()> {
60	    let sums = pack_dir.join("SHA256SUMS");
61	    let msg = std::fs::read(&sums).with_context(|| format!("read {}", sums.display()))?;
62	    let seed = parse_key(seed_hex, 32, "seed")?;
63	    let pair = Ed25519KeyPair::from_seed_unchecked(&seed)
64	        .map_err(|_| anyhow::anyhow!("seed is not a valid ed25519 key"))?;
65	    let sig = pair.sign(&msg);
66	    let out = pack_dir.join(SIG_NAME);
67	    std::fs::write(&out, sig.as_ref()).with_context(|| format!("write {}", out.display()))?;
68	    println!(
69	        "signed {} ({} byte signature over SHA256SUMS)",
70	        out.display(),
71	        sig.as_ref().len()
72	    );
73	    Ok(())
74	}
75	
76	/// Verify `<pack>/SHA256SUMS.sig` against a public-key file. The signature
77	/// chain is: sig → SHA256SUMS → every file the SUMS names, so verifying here
78	/// plus `read_manifest`'s re-hashing proves both integrity and origin.
79	/// `verify_pack` is called BEFORE the pack is materialized, so a failure
80	/// means nothing was indexed.
81	pub fn verify_pack(pack_dir: &Path, public_hex: &str) -> Result<()> {
82	    verify_sig_at(pack_dir, &pack_dir.join(SIG_NAME), public_hex)
83	}
84	
85	/// Same verification with an explicit signature path — `corpus add --from
86	/// <pack.zip>` uses this with the LOOSE signature a release ships beside the
87	/// zip: the sig is never packed inside the zip (it is deliberately absent
88	/// from the SUMS it signs, and the signing step runs after the zip is
89	/// built), so a zip consumer's signature lives in a sibling file.
90	pub fn verify_sig_at(pack_dir: &Path, sig_path: &Path, public_hex: &str) -> Result<()> {
91	    let at = |what: &str| format!("{}: {what}", pack_dir.display());
92	    let sig = std::fs::read(sig_path).with_context(|| at("no SHA256SUMS.sig to verify"))?;
93	    if sig.len() != 64 {
94	        bail!(at(&format!(
95	            "{SIG_NAME} is {} bytes, expected a 64-byte ed25519 signature",
96	            sig.len()
97	        )));
98	    }
99	    let public = parse_key(public_hex, 32, "public key")?;
100	    let msg =
101	        std::fs::read(pack_dir.join("SHA256SUMS")).with_context(|| at("cannot read SHA256SUMS"))?;
102	    let key = UnparsedPublicKey::new(&ring::signature::ED25519, &public);
103	    key.verify(&msg, &sig).map_err(|_| {
104	        anyhow::anyhow!(at(
105	            "signature does not verify — the pack is not from the holder of the expected key, \
106	                 or SHA256SUMS changed after signing"
107	        ))
108	    })?;
109	    Ok(())
110	}
111	
112	/// True when the pack dir carries a signature file (the `corpus add` hint:
113	/// "this pack is signed; pass --verify-sig" — presence is public metadata,
114	/// verification is the consumer's explicit choice).
115	pub fn pack_is_signed(pack_dir: &Path) -> bool {
116	    pack_dir.join(SIG_NAME).is_file()
117	}
118	
119	// ── CLI: `xerj corpus keygen`, `xerj corpus sign` ───────────────────────────
120	
121	const KEYGEN_USAGE: &str = "usage: xerj corpus keygen --out <prefix>
122	
123	writes <prefix>.key (the 32-byte ed25519 seed, hex — SECRET) and <prefix>.pub
124	(the verifying key, hex — publish this). Keep the .key out of the repo and out
125	of logs; it goes to CI secrets and nowhere else.";
126	
127	const SIGN_USAGE: &str = "usage: xerj corpus sign <pack-dir> --key <seed-file>
128	
129	writes <pack-dir>/SHA256SUMS.sig, a detached ed25519 signature over the pack's
130	SHA256SUMS (which covers every pack file). Re-signing overwrites. The pack's
131	checksums stay untouched — signing is a publish step, never a rebuild.";
132	
133	/// Entry point for `xerj corpus keygen|sign <args>` from the dispatcher.
134	pub fn run_sign_cli(sub: &str, args: &[String]) -> i32 {
135	    match sub {
136	        "keygen" => run_keygen(args),
137	        "sign" => run_sign(args),
138	        _ => unreachable!("dispatcher routes only keygen|sign here"),
139	    }
140	}
141	
142	fn run_keygen(args: &[String]) -> i32 {
143	    let mut out: Option<PathBuf> = None;
144	    let mut i = 0;
145	    while i < args.len() {
146	        match args[i].as_str() {
147	            "-h" | "--help" => {
148	                println!("{KEYGEN_USAGE}");
149	                return 0;
150	            }
151	            "--out" => match args.get(i + 1) {
152	                Some(v) => {
153	                    out = Some(PathBuf::from(v));
154	                    i += 1;
155	                }
156	                None => {
157	                    eprintln!("xerj corpus keygen: --out needs a path prefix\n\n{KEYGEN_USAGE}");
158	                    return 2;
159	                }
160	            },
161	            a => {
162	                eprintln!("xerj corpus keygen: unexpected argument '{a}'\n\n{KEYGEN_USAGE}");
163	                return 2;
164	            }
165	        }
166	        i += 1;
167	    }
168	    let Some(prefix) = out else {
169	        eprintln!("xerj corpus keygen: --out is required\n\n{KEYGEN_USAGE}");
170	        return 2;
171	    };
172	    match generate_keypair() {
173	        Ok((seed, public)) => {
174	            let key_path = format!("{}.key", prefix.display());
175	            if Path::new(&key_path).exists() {
176	                eprintln!(
177	                    "xerj corpus keygen: {key_path} already exists — refusing to overwrite a key"
178	                );
179	                return 1;
180	            }
181	            // the documented first run names a directory that does not exist
182	            // yet (`--out tools/packs/keys/<name>`) — create it rather than
183	            // make the user mkdir by hand
184	            if let Some(parent) = Path::new(&key_path).parent() {
185	                if let Err(e) = std::fs::create_dir_all(parent) {
186	                    eprintln!(
187	                        "xerj corpus keygen: cannot create {}: {e}",
188	                        parent.display()
189	                    );
190	                    return 1;
191	                }
192	            }
193	            if let Err(e) = std::fs::write(&key_path, format!("{seed}\n")).and_then(|_| {
194	                std::fs::write(format!("{}.pub", prefix.display()), format!("{public}\n"))
195	            }) {
196	                eprintln!("xerj corpus keygen: cannot write key files: {e}");
197	                return 1;
198	            }
199	            println!("wrote {key_path} (SECRET — CI secret material, never commit)");
200	            println!(
201	                "wrote {}.pub (verifying key — publish next to the pack)",
202	                prefix.display()
203	            );
204	            0
205	        }
206	        Err(e) => {
207	            eprintln!("xerj corpus keygen: {e:#}");
208	            1
209	        }
210	    }
211	}
212	
213	fn run_sign(args: &[String]) -> i32 {
214	    let mut pack: Option<PathBuf> = None;
215	    let mut key: Option<PathBuf> = None;
216	    let mut i = 0;
217	    while i < args.len() {
218	        match args[i].as_str() {
219	            "-h" | "--help" => {
220	                println!("{SIGN_USAGE}");
221	                return 0;
222	            }
223	            "--key" => match args.get(i + 1) {
224	                Some(v) => {
225	                    key = Some(PathBuf::from(v));
226	                    i += 1;
227	                }
228	                None => {
229	                    eprintln!("xerj corpus sign: --key needs a seed file\n\n{SIGN_USAGE}");
230	                    return 2;
231	                }
232	            },
233	            a if a.starts_with('-') => {
234	                eprintln!("xerj corpus sign: unknown flag '{a}'\n\n{SIGN_USAGE}");
235	                return 2;
236	            }
237	            a => {
238	                if pack.is_some() {
239	                    eprintln!("xerj corpus sign: one <pack-dir>, not two\n\n{SIGN_USAGE}");
240	                    return 2;
241	                }
242	                pack = Some(PathBuf::from(a));
243	            }
244	        }
245	        i += 1;
246	    }
247	    let (Some(pack), Some(key)) = (pack, key) else {
248	        eprintln!(
249	            "xerj corpus sign: <pack-dir> and --key <seed-file> are both required\n\n{SIGN_USAGE}"
250	        );
251	        return 2;
252	    };
253	    let seed = match std::fs::read_to_string(&key) {
254	        Ok(s) => s,
255	        Err(e) => {
256	            eprintln!("xerj corpus sign: cannot read {}: {e}", key.display());
257	            return 1;
258	        }
259	    };
260	    match sign_pack(&pack, &seed) {
261	        Ok(()) => 0,
262	        Err(e) => {
263	            eprintln!("xerj corpus sign: {e:#}");
264	            1
265	        }
266	    }
267	}
268	
269	// ── key encoding helpers ────────────────────────────────────────────────────
270	
271	/// Decode hex of an exact byte length, with a name for the error message.
272	/// The keys are 32 raw bytes in hex (64 chars) — not PEM, not pkcs8 — so a
273	/// public key file is copy-pasteable in an issue thread and diffable in a
274	/// repo.
275	fn parse_key(hex: &str, want: usize, what: &str) -> Result<Vec<u8>> {
276	    let t = hex.trim();
277	    if t.len() != want * 2 || !t.chars().all(|c| c.is_ascii_hexdigit()) {
278	        bail!(
279	            "{what} must be {want} bytes as {want}×2 hex chars (got {} chars)",
280	            t.len()
281	        );
282	    }
283	    (0..want)
284	        .map(|i| u8::from_str_radix(&t[i * 2..i * 2 + 2], 16).map_err(|e| anyhow::anyhow!("{e}")))
285	        .collect()
286	}
287	
288	fn hex(bytes: &[u8]) -> String {
289	    bytes.iter().map(|b| format!("{b:02x}")).collect()
290	}
