346	    #[test]
347	    fn sign_then_verify_round_trips_on_a_real_pack() {
348	        let tmp = tempfile::tempdir().unwrap();
349	        let pack_dir = tiny_pack(tmp.path());
350	        let (seed, public) = generate_keypair().unwrap();
351	        sign_pack(&pack_dir, &seed).unwrap();
352	        assert!(pack_is_signed(&pack_dir));
353	        // the signed pack still passes checksum verification (the .sig file
354	        // is not SUMS-covered, by design, and read_manifest ignores it)
355	        pack::read_manifest(&pack_dir).unwrap();
356	        verify_pack(&pack_dir, &public).unwrap();
357	        // and a second key does NOT verify it
358	        let (_, other) = generate_keypair().unwrap();
359	        assert!(verify_pack(&pack_dir, &other)
360	            .unwrap_err()
361	            .to_string()
362	            .contains("does not verify"));
363	    }
