365	    #[test]
366	    fn a_tampered_sums_fails_verification() {
367	        // the whole point of signatures: a self-consistent REBUILD (fresh
368	        // checksums over changed records) has valid checksums, and only the
369	        // signature catches it.
370	        let tmp = tempfile::tempdir().unwrap();
371	        let pack_dir = tiny_pack(tmp.path());
372	        let (seed, public) = generate_keypair().unwrap();
373	        sign_pack(&pack_dir, &seed).unwrap();
374	        // replace a record file AND rewrite SUMS so checksums agree — the
375	        // scenario read_manifest cannot catch
376	        let sums = std::fs::read_to_string(pack_dir.join("SHA256SUMS")).unwrap();
377	        let fname = sums
378	            .lines()
379	            .find(|l| l.ends_with("recipe.toml"))
380	            .unwrap()
381	            .split_once("  ")
382	            .unwrap()
383	            .1
384	            .to_string();
385	        std::fs::write(pack_dir.join(&fname), "# tampered recipe\n").unwrap();
386	        let mut new_sums = String::new();
387	        for line in sums.lines() {
388	            if line.ends_with(&fname) {
389	                let d = sha2::Sha256::digest(b"# tampered recipe\n");
390	                new_sums.push_str(&hex(&d));
391	                new_sums.push_str("  ");
392	                new_sums.push_str(&fname);
393	                new_sums.push('\n');
394	            } else {
395	                new_sums.push_str(line);
396	                new_sums.push('\n');
397	            }
398	        }
399	        std::fs::write(pack_dir.join("SHA256SUMS"), new_sums).unwrap();
400	        pack::read_manifest(&pack_dir).unwrap(); // checksums pass…
401	        let err = verify_pack(&pack_dir, &public).unwrap_err().to_string();
402	        assert!(err.contains("does not verify"), "{err}");
403	    }
