407	        let tmp = tempfile::tempdir().unwrap();
408	        let pack_dir = tiny_pack(tmp.path());
409	        let (seed, public) = generate_keypair().unwrap();
410	        // unsigned pack
411	        assert!(verify_pack(&pack_dir, &public)
412	            .unwrap_err()
413	            .to_string()
414	            .contains("no SHA256SUMS.sig"));
415	        sign_pack(&pack_dir, &seed).unwrap();
416	        // truncated signature
417	        std::fs::write(pack_dir.join(SIG_NAME), vec![0u8; 10]).unwrap();
418	        assert!(verify_pack(&pack_dir, &public)
419	            .unwrap_err()
420	            .to_string()
421	            .contains("10 bytes"));
422	        // malformed public key
