66	/// Build (or rebuild) the pack under `<build_dir>/pack/<name>`.
67	pub fn emit(
68	    build_dir: &Path,
69	    recipe: &Recipe,
70	    recipe_toml: &str,
71	    mut records: Vec<Map<String, Value>>,
72	    stats: &RunStats,
73	    sugg: &crate::harvest::suggest::Suggestions,
74	) -> Result<PackResult> {
75	    let pack_dir = build_dir.join("pack").join(&recipe.name);
76	    let generation = previous_generation(&pack_dir)? + 1;
77	    std::fs::create_dir_all(&pack_dir)
78	        .with_context(|| format!("cannot create {}", pack_dir.display()))?;
79	
80	    // Order first, then refuse duplicate ids: a pack with two records of
81	    // the same id breaks the engine-side _id determinism promise, and a
82	    // duplicate here means identity resolution failed silently.
83	    records.sort_by(|a, b| {
84	        a.get("id")
85	            .and_then(Value::as_str)
86	            .unwrap_or("")
87	            .cmp(b.get("id").and_then(Value::as_str).unwrap_or(""))
88	    });
89	    let mut seen_id = String::new();
90	    for r in &records {
91	        let id = r.get("id").and_then(Value::as_str).unwrap_or("");
92	        if !seen_id.is_empty() && id == seen_id {
93	            bail!("duplicate emitted id '{id}': identity edges failed to merge two records that claim the same id");
94	        }
95	        seen_id = id.to_string();
96	    }
97	
98	    let shards = recipe.emit.shards.min(records.len()).max(1);
99	    let uniform = uniform_keys(&records);
100	
101	    // shard → line buffer; records are id-sorted, so appending preserves
102	    // in-shard order without a second sort.
103	    let mut shard_lines: Vec<String> = vec![String::new(); shards];
104	    for r in &records {
105	        let id = r.get("id").and_then(Value::as_str).unwrap_or("");
106	        let bucket = (xxh3_64(id.as_bytes()) % shards as u64) as usize;
107	        let mut full = r.clone();
108	        for (k, is_array) in &uniform {
109	            full.entry(k.clone()).or_insert_with(|| {
110	                if *is_array {
111	                    Value::Array(Vec::new())
112	                } else {
113	                    Value::Null
114	                }
115	            });
116	        }
117	        shard_lines[bucket].push_str(&super::store::canonical_json(&full));
118	        shard_lines[bucket].push('\n');
119	    }
120	
121	    let mut files: BTreeMap<String, Value> = BTreeMap::new();
122	    for (i, lines) in shard_lines.iter().enumerate() {
123	        let name = format!("records-{:05}.jsonl", i);
124	        if lines.is_empty() {
125	            continue; // small corpora need fewer files than shards
126	        }
127	        let path = pack_dir.join(&name);
128	        std::fs::write(&path, lines.as_bytes())
129	            .with_context(|| format!("cannot write {}", path.display()))?;
130	        let n = lines.lines().count();
131	        files.insert(
132	            name.clone(),
133	            serde_json::json!({ "sha256": hex(&Sha256::digest(lines.as_bytes())), "records": n }),
134	        );
135	    }
136	
137	    // the recipe ships verbatim: it is the pack's provenance, licence
138	    // reasoning included
139	    std::fs::write(pack_dir.join("recipe.toml"), recipe_toml)?;
140	    let recipe_sha = hex(&Sha256::digest(recipe_toml.as_bytes()));
141	
142	    // suggestions — computed by `suggest` from a deterministic sample, never
143	    // applied to anything. Deliberately NOT in the manifest's `files` map
144	    // (that map is records files with per-file counts semantics); they ride
145	    // in SHA256SUMS like every other artifact, so a consumer can verify
146	    // them, and the M3 reader re-hashes them without needing to interpret
147	    // them — packs from before this table existed still verify clean.
148	    std::fs::write(
149	        pack_dir.join("mapping.suggested.json"),
150	        serde_json::to_vec_pretty(&sugg.mapping_doc())?,
151	    )?;
152	    std::fs::write(pack_dir.join("relations.jsonl"), sugg.relations_jsonl())?;
153	    std::fs::write(pack_dir.join("suggestions.md"), sugg.to_markdown())?;
154	
155	    let manifest = serde_json::json!({
156	        "format_version": 1,
157	        "kind": "harvested",
158	        "pack": recipe.name,
159	        "description": recipe.description,
160	        "created_at": chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
161	        "generation": generation,
162	        "recipe_sha256": recipe_sha,
163	        "counts": {
164	            "envelopes": stats.envelopes,
165	            "records": records.len(),
166	            "shards": shards,
167	        },
168	        "sources": stats
169	            .per_source
170	            .iter()
171	            .map(|s| serde_json::to_value(s).expect("SourceStat serializes"))
172	            .collect::<Vec<_>>(),
173	        "files": Value::Object(files.clone().into_iter().collect()),
174	        "tool": { "name": "xerj", "version": env!("CARGO_PKG_VERSION") },
175	    });
176	    let manifest_bytes = serde_json::to_vec_pretty(&manifest)?;
177	    std::fs::write(pack_dir.join("manifest.json"), &manifest_bytes)?;
178	
179	    let mut sums = String::new();
180	    let mut names: Vec<String> = files.keys().cloned().collect();
181	    names.push("recipe.toml".to_string());
182	    names.push("manifest.json".to_string());
183	    names.push("mapping.suggested.json".to_string());
184	    names.push("relations.jsonl".to_string());
185	    names.push("suggestions.md".to_string());
186	    names.sort();
187	    for n in &names {
188	        let bytes = std::fs::read(pack_dir.join(n)).with_context(|| format!("checksumming {n}"))?;
189	        sums.push_str(&hex(&Sha256::digest(&bytes)));
190	        sums.push_str("  ");
191	        sums.push_str(n);
192	        sums.push('\n');
193	    }
194	    std::fs::write(pack_dir.join("SHA256SUMS"), sums)?;
195	
196	    Ok(PackResult {
197	        dir: pack_dir,
198	        generation,
199	        records: records.len(),
200	        shards,
201	    })
202	}
