204	/// The uniform key set: every key any record carries, and whether missing
205	/// values should fill as `[]` (array wherever it appears) or `null`.
206	fn uniform_keys(records: &[Map<String, Value>]) -> BTreeMap<String, bool> {
207	    let mut out: BTreeMap<String, (bool /*any array*/, bool /*all non-null array*/)> =
208	        BTreeMap::new();
209	    for r in records {
210	        for (k, v) in r {
211	            let e = out.entry(k.clone()).or_insert((false, true));
212	            if v.is_array() {
213	                e.0 = true;
214	            } else if !v.is_null() {
215	                e.1 = false;
216	            }
217	        }
218	    }
219	    out.into_iter()
220	        .map(|(k, (any, all))| (k, any && all))
221	        .collect()
222	}
