224	fn previous_generation(pack_dir: &Path) -> Result<u64> {
225	    let Ok(bytes) = std::fs::read(pack_dir.join("manifest.json")) else {
226	        return Ok(0);
227	    };
228	    let v: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
229	    Ok(v.get("generation").and_then(Value::as_u64).unwrap_or(0))
230	}
