268	/// Read and VERIFY a pack directory. Strict where [`emit`] was careful: an
269	/// unknown `format_version` is refused (a reader that silently indexed a
270	/// future format would mis-map fields), every SHA256SUMS line is re-hashed,
271	/// and every records file's sha256 and line count must match the manifest.
272	/// A pack that fails here is corrupt or tampered with, and the error says
273	/// which file and why.
274	pub fn read_manifest(pack_dir: &Path) -> Result<PackMeta> {
275	    let at = |what: &str| format!("{}: {what}", pack_dir.display());
276	
277	    let v: Value = serde_json::from_str(
278	        &std::fs::read_to_string(pack_dir.join("manifest.json"))
279	            .with_context(|| at("cannot read manifest.json"))?,
280	    )
281	    .with_context(|| at("manifest.json is not valid JSON"))?;
282	
283	    let version = v.get("format_version").and_then(Value::as_u64).unwrap_or(0);
284	    if version != 1 {
285	        bail!(at(&format!(
286	            "pack format version {version} is not supported by this build (supported: 1)"
287	        )));
288	    }
289	    let kind = v.get("kind").and_then(Value::as_str).unwrap_or("");
290	    if kind != "harvested" {
291	        bail!(at(&format!(
292	            "not a harvested pack (kind='{kind}') — this reader consumes packs from `xerj \
293	             corpus build`"
294	        )));
295	    }
296	    let name = v.get("pack").and_then(Value::as_str).unwrap_or("");
297	    if name.is_empty() {
298	        bail!(at("manifest has no 'pack' name"));
299	    }
300	
301	    // files: name → {sha256, records}. A file name is about to become a path
302	    // under pack_dir — plain file names only, same charset thinking as the
303	    // zip-entry gate in source.rs.
304	    let mut files: Vec<PackFile> = Vec::new();
305	    let mut declared: BTreeMap<String, String> = BTreeMap::new();
306	    for (fname, meta) in v
307	        .get("files")
308	        .and_then(Value::as_object)
309	        .ok_or_else(|| anyhow::anyhow!(at("manifest has no 'files' map")))?
310	    {
311	        if !plain_file_name(fname) {
312	            bail!(at(&format!(
313	                "manifest names file '{fname}', which is not a plain file name"
314	            )));
315	        }
316	        let sha = meta
317	            .get("sha256")
318	            .and_then(Value::as_str)
319	            .filter(|s| s.len() == 64 && s.chars().all(|c| c.is_ascii_hexdigit()))
320	            .ok_or_else(|| anyhow::anyhow!(at(&format!("file '{fname}' has no valid sha256"))))?;
321	        let records =
322	            meta.get("records").and_then(Value::as_u64).ok_or_else(|| {
323	                anyhow::anyhow!(at(&format!("file '{fname}' has no record count")))
324	            })? as usize;
325	        declared.insert(fname.clone(), sha.to_string());
326	        files.push(PackFile {
327	            name: fname.clone(),
328	            records,
329	        });
330	    }
331	    files.sort_by(|a, b| a.name.cmp(&b.name));
332	
333	    // SHA256SUMS is the outer truth: re-hash EVERYTHING it names.
334	    let sums_raw = std::fs::read_to_string(pack_dir.join("SHA256SUMS"))
335	        .with_context(|| at("cannot read SHA256SUMS"))?;
336	    let mut sums: BTreeMap<String, String> = BTreeMap::new();
337	    for line in sums_raw.lines() {
338	        let line = line.trim_end_matches('\r');
339	        if line.is_empty() {
340	            continue;
341	        }
342	        let Some((sha, fname)) = line.split_once("  ") else {
343	            bail!(at(&format!(
344	                "SHA256SUMS line is not '<sha>  <file>': '{line}'"
345	            )));
346	        };
347	        if !plain_file_name(fname) {
348	            bail!(at(&format!(
349	                "SHA256SUMS names '{fname}', which is not a plain file name"
350	            )));
351	        }
352	        sums.insert(fname.to_string(), sha.to_string());
353	    }
354	    for required in ["manifest.json", "recipe.toml"] {
355	        if !sums.contains_key(required) {
356	            bail!(at(&format!("SHA256SUMS does not cover {required}")));
357	        }
358	    }
359	    for (fname, sha) in &declared {
360	        if !sums.contains_key(fname) {
361	            bail!(at(&format!("SHA256SUMS does not cover {fname}")));
362	        }
363	        if &sums[fname] != sha {
364	            bail!(at(&format!(
365	                "{fname}: manifest sha256 and SHA256SUMS disagree — the pack is inconsistent"
366	            )));
367	        }
368	    }
369	    for (fname, sha) in &sums {
370	        let bytes = std::fs::read(pack_dir.join(fname))
371	            .with_context(|| at(&format!("SHA256SUMS names {fname}, which is missing")))?;
372	        let got = hex(&Sha256::digest(&bytes));
373	        if &got != sha {
374	            bail!(at(&format!(
375	                "{fname}: checksum mismatch (want {sha}, got {got}) — corrupt or tampered"
376	            )));
377	        }
378	    }
379	
380	    // line counts: the manifest's per-file record counts must be the truth
381	    for f in &files {
382	        let n = std::fs::read_to_string(pack_dir.join(&f.name))
383	            .with_context(|| at(&format!("cannot read {}", f.name)))?
384	            .lines()
385	            .filter(|l| !l.trim().is_empty())
386	            .count();
387	        if n != f.records {
388	            bail!(at(&format!(
389	                "{}: manifest says {} records, file holds {n}",
390	                f.name, f.records
391	            )));
392	        }
393	    }
394	
395	    let sources = v
396	        .get("sources")
397	        .and_then(Value::as_array)
398	        .ok_or_else(|| anyhow::anyhow!(at("manifest has no 'sources' array")))?
399	        .iter()
400	        .map(|s| PackSource {
401	            slug: s
402	                .get("slug")
403	                .and_then(Value::as_str)
404	                .unwrap_or("")
405	                .to_string(),
406	            licence: s
407	                .get("licence")
408	                .and_then(Value::as_str)
409	                .unwrap_or("")
410	                .to_string(),
411	            url: s
412	                .get("url")
413	                .and_then(Value::as_str)
414	                .filter(|u| !u.is_empty())
415	                .map(str::to_string),
416	            watermark: s
417	                .get("watermark")
418	                .and_then(Value::as_str)
419	                .filter(|w| !w.is_empty())
420	                .map(str::to_string),
421	        })
422	        .collect::<Vec<PackSource>>();
423	    if sources.is_empty() {
424	        bail!(at("manifest declares no sources"));
425	    }
426	    if sources.iter().any(|s| s.slug.is_empty()) {
427	        bail!(at("a manifest source has no slug"));
428	    }
429	
430	    Ok(PackMeta {
431	        name: name.to_string(),
432	        description: v
433	            .get("description")
434	            .and_then(Value::as_str)
435	            .unwrap_or("")
436	            .to_string(),
437	        generation: v.get("generation").and_then(Value::as_u64).unwrap_or(0),
438	        records: v
439	            .get("counts")
440	            .and_then(|c| c.get("records"))
441	            .and_then(Value::as_u64)
442	            .unwrap_or(0) as usize,
443	        sources,
444	        files,
445	    })
446	}
