448	/// A name that may be joined onto a pack dir without escaping it: no path
449	/// separators, no `..`, no drive letters, not hidden, not empty.
450	fn plain_file_name(name: &str) -> bool {
451	    !name.is_empty()
452	        && !name.starts_with('.')
453	        && !name.contains('/')
454	        && !name.contains('\\')
455	        && !name.contains(':')
456	        && name != "."
457	        && name != ".."
458	}
