520	            &recipe("t", 4),
521	            "# recipe\n",
522	            records.clone(),
523	            &stats(),
524	            &sugg(&records),
525	        )
526	        .unwrap();
527	        assert_eq!(r1.records, 2);
528	        assert_eq!(r1.generation, 1);
529	
530	        // every shard file's records carry BOTH keys
531	        for entry in std::fs::read_dir(&r1.dir).unwrap().flatten() {
532	            let name = entry.file_name().to_string_lossy().to_string();
533	            if !name.starts_with("records-") {
534	                continue;
535	            }
536	            for line in std::fs::read_to_string(entry.path()).unwrap().lines() {
537	                let v: Value = serde_json::from_str(line).unwrap();
538	                assert!(v.get("aliases").is_some(), "array key filled");
539	                assert!(v.get("severity").is_some(), "scalar key filled");
540	                let id = v["id"].as_str().unwrap();
541	                if id == "a" {
542	                    assert_eq!(v["aliases"], json!(["X1"]));
543	                    assert_eq!(v["severity"], json!(null));
544	                } else {
545	                    assert_eq!(v["aliases"], json!([]), "array key fills empty");
546	                    assert_eq!(v["severity"], json!("HIGH"));
547	                }
548	            }
549	        }
550	
551	        // rebuild from a DIFFERENT input order → byte-identical records
552	        let mut shuffled = records.clone();
553	        shuffled.reverse();
554	        let before: Vec<(String, Vec<u8>)> = std::fs::read_dir(&r1.dir)
555	            .unwrap()
556	            .flatten()
557	            .map(|e| {
558	                (
559	                    e.file_name().to_string_lossy().to_string(),
560	                    std::fs::read(e.path()).unwrap(),
561	                )
562	            })
563	            .filter(|(n, _)| n.starts_with("records-"))
564	            .collect();
565	        let r2 = emit(
566	            tmp.path(),
567	            &recipe("t", 4),
568	            "# recipe\n",
569	            shuffled,
570	            &stats(),
571	            &sugg(&records),
572	        )
573	        .unwrap();
574	        assert_eq!(r2.generation, 2, "generation advances");
575	        for (name, bytes) in before {
576	            assert_eq!(
577	                std::fs::read(r2.dir.join(&name)).unwrap(),
578	                bytes,
579	                "{name} identical"
580	            );
581	        }
582	    }
