1	//! Source adapters: turn a recipe `[[sources]]` entry into a directory to
2	//! walk, plus the upstream watermark that lets an unchanged source be
3	//! skipped wholesale on the next run.
4	//!
5	//! Kinds:
6	//! - `dir`     — walk a recipe-relative directory (the fixture/local kind)
7	//! - `http-zip`— download a zip, extract into the cache, walk the
8	//!   extraction. No watermark: the zip is re-downloaded every run and the
9	//!   content store dedups what did not change (correctness lives there,
10	//!   watermarks are only an optimization).
11	//! - `git`     — promisor shallow checkout at `rev` (pinned) or the remote
12	//!   HEAD (tracking). Watermark = HEAD sha: unchanged tree ⇒ the walk is
13	//!   skipped entirely this run.
14	//!
15	//! Zip extraction is defensive by default: entry names are normalized and
16	//! any path escaping the extraction root (zip-slip), absolute path, or
17	//! symlink entry is skipped and COUNTED, never trusted — dump URLs are
18	//! fetched from the open internet.
19	
20	use std::io::Read;
21	use std::path::{Component, Path, PathBuf};
22	
23	use anyhow::{bail, Context, Result};
24	
25	use super::httpget;
26	use super::recipe::SourceSpec;
27	
28	/// Total decompressed cap for one zip. Real advisory dumps are well under
29	/// this; the cap exists because a zip's declared sizes are untrusted and a
30	/// 3 MiB file can claim to expand to terabytes.
31	const MAX_EXTRACT_BYTES: u64 = 2 << 30;
32	
33	#[derive(Debug)]
34	pub struct Fetched {
35	    /// The directory the glob walk starts from.
36	    pub root: PathBuf,
37	    /// Current upstream version marker, if the kind has one.
38	    pub watermark: Option<String>,
39	    /// The watermark matches the previous run's: the caller should skip
40	    /// walking AND pruning this source (everything it stored is still live).
41	    pub unchanged: bool,
42	}
43	
44	/// Where a source's watermark from the previous run is kept.
45	fn watermark_path(cache_dir: &Path, slug: &str) -> PathBuf {
46	    cache_dir.join(format!("{slug}.watermark"))
47	}
48	
49	/// Materialize a source. `cache_dir` is `<build>/cache`; it only exists to
50	/// make network kinds incremental.
51	pub fn fetch(src: &SourceSpec, recipe_dir: &Path, cache_dir: &Path) -> Result<Fetched> {
52	    match src.kind {
53	        super::recipe::SourceKind::Dir => Ok(Fetched {
54	            root: recipe_dir.join(src.path.as_deref().unwrap_or(".")),
55	            watermark: None,
56	            unchanged: false,
57	        }),
58	        super::recipe::SourceKind::HttpZip => {
59	            let url = src.url.as_deref().unwrap_or_default();
60	            let zip_path = cache_dir.join(format!("{}.zip", src.slug));
61	            httpget::download(url, &zip_path)
62	                .with_context(|| format!("source '{}': fetch", src.slug))?;
63	            let root = cache_dir.join(&src.slug);
64	            extract_zip(&zip_path, &root)
65	                .with_context(|| format!("source '{}': extract", src.slug))?;
66	            Ok(Fetched {
67	                root,
68	                watermark: None,
69	                unchanged: false,
70	            })
71	        }
72	        super::recipe::SourceKind::Git => {
73	            let url = src.url.as_deref().unwrap_or_default();
74	            let root = cache_dir.join(&src.slug);
75	            let rev = src.rev.as_deref().unwrap_or("HEAD");
76	            let watermark = git_checkout(&root, url, rev, &src.slug)?;
77	            let prev = std::fs::read_to_string(watermark_path(cache_dir, &src.slug))
78	                .map(|s| s.trim().to_string())
79	                .unwrap_or_default();
80	            Ok(Fetched {
81	                root,
82	                watermark: Some(watermark.clone()),
83	                unchanged: !watermark.is_empty() && watermark == prev,
84	            })
85	        }
86	    }
87	}
88	
89	/// Persist a source's watermark after its harvest fully succeeded (never
90	/// before — a failed run must re-walk).
91	pub fn save_watermark(cache_dir: &Path, slug: &str, watermark: &str) -> Result<()> {
92	    std::fs::create_dir_all(cache_dir)?;
93	    std::fs::write(watermark_path(cache_dir, slug), watermark)
94	        .with_context(|| format!("save watermark for '{slug}'"))
95	}
