54	const BUILD_USAGE: &str = "usage: xerj corpus build <name> [--recipe <path>] [--fresh]
55	
56	build (or incrementally refresh) a harvested corpus pack:
57	  1. load the recipe (default $XERJ_CODE_HOME/recipes/<name>.toml)
58	  2. harvest every declared source into the content store
59	     (already-stored records are skipped — that is the point)
60	  3. resolve identity, merge duplicates, emit a deterministic pack
61	     under $XERJ_CODE_HOME/builds/<name>/pack/<name>/
62	
63	--fresh discards the build state first (full re-harvest).";
64	
65	/// Entry point from the corpus dispatcher. 0 = pack built, 1 = failure,
66	/// 2 = usage error.
67	pub fn run_build(args: &[String]) -> i32 {
68	    match run_build_inner(args, &code_root()) {
69	        Ok(code) => code,
70	        Err(e) => {
71	            eprintln!("xerj corpus build: {e:#}");
72	            1
73	        }
74	    }
75	}
