77	fn run_build_inner(args: &[String], home: &Path) -> Result<i32> {
78	    let mut name: Option<String> = None;
79	    let mut recipe_path: Option<PathBuf> = None;
80	    let mut fresh = false;
81	    let mut it = args.iter();
82	    while let Some(a) = it.next() {
83	        match a.as_str() {
84	            "--recipe" => {
85	                recipe_path = Some(PathBuf::from(it.next().context("--recipe needs a path")?));
86	            }
87	            "--fresh" => fresh = true,
88	            "-h" | "--help" | "help" => {
89	                println!("{BUILD_USAGE}");
90	                return Ok(0);
91	            }
92	            s if s.starts_with('-') => bail!("unknown flag '{s}'\n\n{BUILD_USAGE}"),
93	            s => {
94	                if name.replace(s.to_string()).is_some() {
95	                    bail!("unexpected second name '{s}'\n\n{BUILD_USAGE}");
96	                }
97	            }
98	        }
99	    }
100	    let Some(name) = name else {
101	        eprintln!("{BUILD_USAGE}");
102	        return Ok(2);
103	    };
104	
105	    let recipe_file = match recipe_path {
106	        Some(p) => p,
107	        None => home.join("recipes").join(format!("{name}.toml")),
108	    };
109	    if !recipe_file.is_file() {
110	        bail!(
111	            "no recipe for '{name}' at {} (pass --recipe <path>, or create it there)",
112	            recipe_file.display()
113	        );
114	    }
115	    let recipe = recipe::load(&recipe_file)?;
116	    if recipe.name != name {
117	        bail!(
118	            "recipe at {} builds corpus '{}', not '{}' — the name must match",
119	            recipe_file.display(),
120	            recipe.name,
121	            name
122	        );
123	    }
124	    let recipe_dir = recipe_file
125	        .parent()
126	        .map(Path::to_path_buf)
127	        .unwrap_or_else(|| PathBuf::from("."));
128	    let recipe_toml = std::fs::read_to_string(&recipe_file)?;
129	
130	    let build_dir = home.join("builds").join(&recipe.name);
131	    if fresh && build_dir.exists() {
132	        std::fs::remove_dir_all(&build_dir)
133	            .with_context(|| format!("--fresh: cannot clear {}", build_dir.display()))?;
134	    }
135	    let store_dir = build_dir.join("store");
136	    let cache_dir = build_dir.join("cache");
137	
138	    // ── harvest into the content store ───────────────────────────────────
139	    let mut per_source = Vec::new();
140	    for src in &recipe.sources {
141	        let fetched = source::fetch(src, &recipe_dir, &cache_dir)?;
142	        let mut stat = SourceStat {
143	            slug: src.slug.clone(),
144	            kind: kind_name(src.kind).to_string(),
145	            path: src.path.clone(),
146	            url: src.url.clone(),
147	            licence: src.licence.clone(),
148	            watermark: fetched.watermark.clone(),
149	            unchanged: fetched.unchanged,
150	            records: 0,
151	            new: 0,
152	            skipped: 0,
153	            pruned: 0,
154	        };
155	        if fetched.unchanged {
156	            // The whole upstream tree is byte-identical to the previous run:
157	            // skip the walk AND the prune — every envelope this source ever
158	            // stored is still live, and pruning needs the full key set.
159	            per_source.push(stat);
160	            continue;
161	        }
162	        let files = walk(&fetched.root, &src.glob)?;
163	        let mut keys = HashSet::new();
164	        for (rel, path) in files {
165	            for value in parse_file(&path)? {
166	                let mut env = normalize::normalize(src.format, &value);
167	                env.insert(SRC.into(), Value::String(src.slug.clone()));
168	                env.insert(
169	                    SRC_URL.into(),
170	                    Value::String(src.url.clone().unwrap_or_default()),
171	                );
172	                env.insert(SRC_PATH.into(), Value::String(rel.clone()));
173	                env.insert(LICENCE.into(), Value::String(src.licence.clone()));
174	                let (key, was_new) = store::put(&store_dir, &src.slug, &env)?;
175	                keys.insert(key);
176	                stat.records += 1;
177	                if was_new {
178	                    stat.new += 1;
179	                } else {
180	                    stat.skipped += 1;
181	                }
182	            }
183	        }
184	        stat.pruned = store::prune(&store_dir, &src.slug, &keys);
185	        // persist the watermark only after the source's harvest fully
186	        // succeeded — a failed run must re-walk
187	        if let Some(wm) = &fetched.watermark {
188	            source::save_watermark(&cache_dir, &src.slug, wm)?;
189	        }
190	        per_source.push(stat);
191	    }
192	
193	    // ── identity + merge over the FULL store (not just this run's files) ──
194	    let slugs: HashSet<String> = recipe.sources.iter().map(|s| s.slug.clone()).collect();
195	    let envelopes = store::read_all(&store_dir, &slugs);
196	    let clusters = identity::cluster(&envelopes, &recipe.identity);
197	    let merge_order = if recipe.merge.precedence.is_empty() {
198	        recipe.identity.canonical_source_order.clone()
199	    } else {
200	        recipe.merge.precedence.clone()
201	    };
202	    let mut records = Vec::with_capacity(clusters.len());
203	    for c in &clusters {
204	        let members: Vec<&Map<String, Value>> = c.members.iter().map(|&i| &envelopes[i]).collect();
205	        records.push(identity::merge_cluster(
206	            &members,
207	            &merge_order,
208	            &recipe.envelope,
209	            &recipe.merge,
210	            &recipe.derived,
211	        ));
212	    }
213	
214	    // ── emit ──────────────────────────────────────────────────────────────
215	    let stats = RunStats {
216	        envelopes: envelopes.len(),
217	        per_source,
218	    };
219	    // suggestions from a deterministic sample — the recipe author's feedback
220	    // loop, never applied to the records or the index
221	    let suggestions = suggest::analyze(&records, recipe.suggest.sample);
222	    let result = pack::emit(
223	        &build_dir,
224	        &recipe,
225	        &recipe_toml,
226	        records,
227	        &stats,
228	        &suggestions,
229	    )?;
230	
231	    // run report: the machine-readable twin of the stdout summary, with the
232	    // watermarks a scheduled rebuild (M6) will diff against
233	    let report = serde_json::json!({
234	        "finished_at": chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
235	        "pack": recipe.name,
236	        "generation": result.generation,
237	        "records": result.records,
238	        "envelopes": stats.envelopes,
239	        "sources": stats.per_source.iter()
240	            .map(|s| serde_json::to_value(s).expect("SourceStat serializes"))
241	            .collect::<Vec<_>>(),
242	    });
243	    std::fs::write(
244	        build_dir.join("report.json"),
245	        serde_json::to_vec_pretty(&report)?,
246	    )
247	    .with_context(|| format!("write {}", build_dir.join("report.json").display()))?;
248	
249	    println!(
250	        "built '{}' generation {}: {} envelopes → {} records, {} shard file(s)",
251	        recipe.name, result.generation, stats.envelopes, result.records, result.shards
252	    );
253	    for s in &stats.per_source {
254	        if s.unchanged {
255	            println!(
256	                "  {}: unchanged (watermark {})",
257	                s.slug,
258	                s.watermark.clone().unwrap_or_default()
259	            );
260	            continue;
261	        }
262	        println!(
263	            "  {}: {} record(s) — {} new, {} skipped, {} pruned ({})",
264	            s.slug, s.records, s.new, s.skipped, s.pruned, s.licence
265	        );
266	    }
267	    println!("pack: {}", result.dir.display());
268	    println!(
269	        "  suggestions: {} field(s), {} relation(s) — see {}",
270	        suggestions.fields.len(),
271	        suggestions.relations.len(),
272	        result.dir.join("suggestions.md").display()
273	    );
274	    Ok(0)
275	}
