285	// ── dir source ──────────────────────────────────────────────────────────────
286	
287	/// Recursively list files under `root` matching `glob`, as
288	/// (posix-relative-path, absolute-path), sorted — directory iteration order
289	/// must never reach the output.
290	fn walk(root: &Path, glob: &str) -> Result<Vec<(String, PathBuf)>> {
291	    let re = glob_regex(glob);
292	    let mut out = Vec::new();
293	    fn recurse(dir: &Path, root: &Path, re: &regex::Regex, out: &mut Vec<(String, PathBuf)>) {
294	        let Ok(entries) = std::fs::read_dir(dir) else {
295	            return;
296	        };
297	        for e in entries.flatten() {
298	            let p = e.path();
299	            if p.is_dir() {
300	                recurse(&p, root, re, out);
301	            } else {
302	                let rel = p.strip_prefix(root).unwrap_or(&p);
303	                let rel = rel.to_string_lossy().replace('\\', "/");
304	                if re.is_match(&rel) {
305	                    out.push((rel, p));
306	                }
307	            }
308	        }
309	    }
310	    recurse(root, root, &re, &mut out);
311	    out.sort();
312	    Ok(out)
313	}
314	
315	/// Minimal glob → regex: `**` spans directories (`**/` also matches zero
316	/// directories), `*` stays inside one segment, `?` is one char. Recipes
317	/// need path matching, not the full glob grammar; if a recipe ever needs
318	/// character classes we take a real glob crate rather than growing this.
319	fn glob_regex(glob: &str) -> regex::Regex {
320	    let mut re = String::from("^");
321	    let mut chars = glob.chars().peekable();
322	    while let Some(c) = chars.next() {
323	        match c {
324	            '*' => {
325	                if chars.peek() == Some(&'*') {
326	                    chars.next();
327	                    if chars.peek() == Some(&'/') {
328	                        chars.next();
329	                        re.push_str("(.*/)?");
330	                    } else {
331	                        re.push_str(".*");
332	                    }
333	                } else {
334	                    re.push_str("[^/]*");
335	                }
336	            }
337	            '?' => re.push_str("[^/]"),
338	            other => re.push_str(&regex::escape(&other.to_string())),
339	        }
340	    }
341	    re.push('$');
342	    regex::Regex::new(&re).expect("glob translation always yields a valid regex")
343	}
344	
345	/// Parse one harvested file: `.json`/`.jsonl`/`.ndjson`/`.md`. A `.json`
346	/// array yields its elements; `.jsonl` yields one per non-empty line; a
347	/// `.md` yields its raw text as ONE string value — the format adapter (e.g.
348	/// `rustsec-md`) owns interpreting it, so an `.md` globbed by a json-format
349	/// source is visible junk, not a silent parse error. Other extensions are
350	/// skipped by the glob, not here — reaching this with an unlisted type is a
351	/// hard error, not a silent drop.
352	fn parse_file(path: &Path) -> Result<Vec<Value>> {
353	    let raw =
354	        std::fs::read_to_string(path).with_context(|| format!("cannot read {}", path.display()))?;
355	    let name = path
356	        .file_name()
357	        .and_then(|n| n.to_str())
358	        .unwrap_or_default()
359	        .to_lowercase();
360	    if name.ends_with(".md") || name.ends_with(".markdown") {
361	        return Ok(vec![Value::String(raw)]);
362	    }
363	    let jsonl = name.ends_with(".jsonl") || name.ends_with(".ndjson");
364	    if jsonl {
365	        let mut out = Vec::new();
366	        for (n, line) in raw.lines().enumerate() {
367	            let line = line.trim();
368	            if line.is_empty() {
369	                continue;
370	            }
371	            let v: Value = serde_json::from_str(line)
372	                .with_context(|| format!("{}:{}: not valid JSON", path.display(), n + 1))?;
373	            out.push(v);
374	        }
375	        Ok(out)
376	    } else {
377	        let v: Value = serde_json::from_str(&raw)
378	            .with_context(|| format!("{}: not valid JSON", path.display()))?;
379	        Ok(match v {
380	            Value::Array(a) => a,
381	            other => vec![other],
382	        })
383	    }
384	}
