391	    #[test]
392	    fn glob_matches_paths_like_a_recipe_expects() {
393	        let re = glob_regex("**/*.json");
394	        assert!(re.is_match("a.json"));
395	        assert!(re.is_match("deep/nested/a.json"));
396	        assert!(!re.is_match("a.jsonl"));
