527	    fn read_records(pack: &Path) -> Vec<Map<String, Value>> {
528	        let manifest: Value =
529	            serde_json::from_str(&std::fs::read_to_string(pack.join("manifest.json")).unwrap())
530	                .unwrap();
531	        let mut out = Vec::new();
532	        for name in manifest["files"].as_object().unwrap().keys() {
533	            for line in std::fs::read_to_string(pack.join(name)).unwrap().lines() {
534	                out.push(serde_json::from_str(line).unwrap());
535	            }
536	        }
537	        out.sort_by_key(|r: &Map<String, Value>| {
538	            r.get("id")
539	                .and_then(Value::as_str)
540	                .unwrap_or("")
541	                .to_string()
542	        });
543	        out
544	    }
