1	//! The content-addressed envelope store — "skip already stored" as a
2	//! filesystem fact, not a promise.
3	//!
4	//! Each normalized record plus its provenance becomes ONE immutable JSON
5	//! file named `<slug>.<xxh3_128-of-canonical-json>.json`. File presence IS
6	//! the dedup index: a re-run recomputes the key and skips if the file
7	//! exists, the same recomputed-never-trusted philosophy as `ids.rs` (same
8	//! content ⇒ same key ⇒ the write converges). No database, no journal —
9	//! crash at any point and the next run converges.
10	//!
11	//! The canonical form is key-sorted JSON with f64 floats in
12	//! shortest-round-trip form — deterministic for the same logical content
13	//! regardless of the input file's key order. (Sorting is explicit: the
14	//! workspace enables serde_json's `preserve_order` for the engine's
15	//! document store, which would otherwise bake insertion order in.)
16	
17	use std::collections::HashSet;
18	use std::io;
19	use std::path::{Path, PathBuf};
20	
21	use serde_json::{Map, Value};
22	use xxhash_rust::xxh3::xxh3_128;
23	
24	/// Cap on flattened fields per envelope, matching the extractor's own cap
25	/// (`extract::MAX_FIELDS_PER_RECORD`): an envelope fatter than what the
26	/// index path would keep would silently disagree with the indexed record.
27	pub(crate) const MAX_FIELDS: usize = 512;
28	
29	/// Canonical JSON for content hashing: sorted-key serialization. The
30	/// workspace enables serde_json's `preserve_order` (xerj-common), so `Map`
31	/// is an IndexMap and `to_string` would bake in INSERTION order — which is
32	/// exactly what canonical form must not do. Sorting through a `BTreeMap`
33	/// sidesteps the feature entirely.
34	pub fn canonical_json(env: &Map<String, Value>) -> String {
35	    let sorted: std::collections::BTreeMap<&String, &Value> = env.iter().collect();
36	    serde_json::to_string(&sorted).unwrap_or_default()
37	}
38	
39	/// The store key for an envelope: xxh3_128 of the canonical JSON, hex.
40	/// 128-bit so an accidental collision across a multi-million-record store is
41	/// not a scenario to reason about.
42	pub fn key_of(env: &Map<String, Value>) -> String {
43	    format!("{:032x}", xxh3_128(canonical_json(env).as_bytes()))
44	}
45	
46	/// Store one envelope. Returns `true` when it was NEW (written), `false`
47	/// when an identical envelope was already stored (skipped). The write is
48	/// atomic (tmp + rename): a partial file never exists under its final name.
49	pub fn put(store_dir: &Path, slug: &str, env: &Map<String, Value>) -> io::Result<(String, bool)> {
50	    let key = key_of(env);
51	    let path = file_for(store_dir, slug, &key);
52	    if path.exists() {
53	        return Ok((key, false));
54	    }
55	    std::fs::create_dir_all(store_dir)?;
56	    let tmp = path.with_extension("json.tmp");
57	    std::fs::write(&tmp, canonical_json(env))?;
58	    std::fs::rename(&tmp, &path)?;
59	    Ok((key, true))
60	}
61	
62	fn file_for(store_dir: &Path, slug: &str, key: &str) -> PathBuf {
63	    store_dir.join(format!("{slug}.{key}.json"))
64	}
65	
66	/// Every envelope whose `_src` is one of `slugs`, in filename order (the
67	/// deterministic iteration order every downstream stage relies on).
68	/// Envelopes from sources the current recipe no longer declares are left on
69	/// disk but not returned — a retired source must not haunt the cluster set.
70	/// Each returned map carries the file's store key under the `KEY` sentinel
71	/// so member ordering can fall back to it; `put` computes the key BEFORE
72	/// injection, so the sentinel is never part of any stored content.
73	pub fn read_all(store_dir: &Path, slugs: &HashSet<String>) -> Vec<Map<String, Value>> {
74	    let mut out = Vec::new();
75	    let Ok(entries) = std::fs::read_dir(store_dir) else {
76	        return out;
77	    };
78	    let mut names: Vec<String> = entries
79	        .flatten()
80	        .filter(|e| e.path().extension().and_then(|x| x.to_str()) == Some("json"))
81	        .filter_map(|e| e.file_name().to_str().map(str::to_string))
82	        .collect();
83	    names.sort();
84	    for name in names {
85	        // "<slug>.<32-hex>.json" — split from the RIGHT: slugs may contain
86	        // dots themselves, the key never does.
87	        let Some(rest) = name.strip_suffix(".json") else {
88	            continue;
89	        };
90	        let Some((slug, key)) = rest.rsplit_once('.') else {
91	            continue;
92	        };
93	        if !slugs.contains(slug) {
94	            continue;
95	        }
96	        if let Ok(raw) = std::fs::read_to_string(store_dir.join(&name)) {
97	            if let Ok(Value::Object(mut m)) = serde_json::from_str::<Value>(&raw) {
98	                m.insert(super::identity::KEY.into(), Value::String(key.to_string()));
99	                out.push(m);
100	            }
101	        }
102	    }
103	    out
104	}
105	
106	/// Drop envelopes of `slug` that this run did NOT re-put — a file deleted
107	/// upstream, or a record the normalizer no longer emits. Returns how many
108	/// files were removed. Scoped to one slug so a PARTIAL harvest of another
109	/// source (network watermark, M2) can never prune what it did not walk.
110	pub fn prune(store_dir: &Path, slug: &str, live_keys: &HashSet<String>) -> usize {
111	    let Ok(entries) = std::fs::read_dir(store_dir) else {
112	        return 0;
113	    };
114	    let mut removed = 0usize;
115	    for e in entries.flatten() {
116	        let name = e.file_name().to_string_lossy().to_string();
117	        let Some(rest) = name.strip_prefix(&format!("{slug}.")) else {
118	            continue;
119	        };
120	        let Some(key) = rest.strip_suffix(".json") else {
121	            continue;
122	        };
123	        if live_keys.contains(key) {
124	            continue;
125	        }
126	        if std::fs::remove_file(e.path()).is_ok() {
127	            removed += 1;
128	        }
129	    }
130	    removed
131	}
