27	/// Reserved envelope key names. Every emitted record carries these; derived
28	/// fields and passthrough data may not clobber them (validation refuses a
29	/// recipe that tries — a silent clobber here would make `xerj code` and the
30	/// ES-compat query surface disagree about what a record is).
31	pub const RESERVED_KEYS: &[&str] = &[
32	    "id",
33	    "title",
34	    "body",
35	    "defs",
36	    "licence",
37	    "source",
38	    "sources",
39	    "source_url",
40	    "modified",
41	    "origin",
42	];
