366	/// A slug becomes a filename component in the content store
367	/// (`<slug>.<key>.json`), so it is gated to a safe charset the way corpus
368	/// and repo names are — but locally, because slugs are a builder concept.
369	fn valid_slug(slug: &str) -> Result<()> {
370	    let ok = !slug.is_empty()
371	        && slug.len() <= 64
372	        && slug
373	            .chars()
374	            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_' || c == '.')
375	        && !slug.starts_with('.');
376	    if !ok {
377	        bail!("source slug '{slug}' must be 1-64 chars of [A-Za-z0-9._-], not starting with '.'");
378	    }
379	    Ok(())
380	}
