382	/// Read, validate and compile a recipe. Every error names the file and the
383	/// offending key — a recipe that fails here must never half-run.
384	pub fn load(path: &Path) -> Result<Recipe> {
385	    let raw = std::fs::read_to_string(path)
386	        .with_context(|| format!("cannot read recipe {}", path.display()))?;
387	    let file: RawRecipe = toml::from_str(&raw).map_err(|e| {
388	        // the toml error names the unknown key/line — keep it in the message
389	        anyhow::anyhow!("{}: recipe parse error: {e}", path.display())
390	    })?;
391	    compile(path, file)
392	}
393	
394	fn compile(path: &Path, file: RawRecipe) -> Result<Recipe> {
395	    let at = |what: &str| format!("{}: {}", path.display(), what);
396	
397	    if file.recipe.format != 1 {
398	        bail!(at(&format!(
399	            "recipe format {} is not supported by this build (supported: 1)",
400	            file.recipe.format
401	        )));
402	    }
403	    let name = file.recipe.name.trim().to_string();
404	    if let Err(e) = xerj_common::xccode::pathgate::valid_corpus_name(&name) {
405	        bail!(at(&format!("recipe name '{name}': {e}")));
406	    }
407	
408	    if file.sources.is_empty() {
409	        bail!(at("recipe declares no [[sources]]"));
410	    }
411	    let mut slugs: Vec<&str> = Vec::new();
412	    let mut sources = Vec::new();
413	    for s in &file.sources {
