29	/// Normalize one record under `format` into flat key paths.
30	pub fn normalize(format: Format, v: &Value) -> Map<String, Value> {
31	    match format {
32	        Format::Flat => flatten(v),
33	        Format::Osv => normalize_osv(v),
34	        Format::RustsecMd => match v {
35	            Value::String(s) => normalize_rustsec_md(s),
36	            other => flatten(other),
37	        },
38	    }
39	}
