41	// ── generic flattening ──────────────────────────────────────────────────────
42	
43	/// Flatten any JSON value into flat keys, `extract::flatten_object`
44	/// semantics. A non-object top level becomes `{"value": v}` so envelope
45	/// mapping still has something to point at.
46	pub fn flatten(v: &Value) -> Map<String, Value> {
47	    let mut out = Map::new();
48	    match v {
49	        Value::Object(m) => {
50	            for (k, vv) in m {
51	                flatten_into(k, vv.clone(), 0, &mut out);
52	            }
53	        }
54	        other => {
55	            out.insert("value".to_string(), other.clone());
56	        }
57	    }
58	    out
59	}
60	
61	fn flatten_into(key: &str, v: Value, depth: usize, out: &mut Map<String, Value>) {
62	    if out.len() >= super::MAX_FIELDS {
63	        return;
64	    }
65	    match v {
66	        Value::Object(m) => {
67	            if depth < 2 {
68	                for (k, vv) in m {
69	                    flatten_into(&format!("{key}_{k}"), vv, depth + 1, out);
70	                }
71	            } else {
72	                out.insert(
73	                    key.to_string(),
74	                    Value::String(serde_json::to_string(&m).unwrap_or_default()),
75	                );
76	            }
77	        }
78	        Value::Array(a) => {
79	            if a.iter().all(|e| !e.is_object() && !e.is_array()) {
80	                out.insert(key.to_string(), Value::Array(a));
81	            } else {
82	                out.insert(
83	                    key.to_string(),
84	                    Value::String(serde_json::to_string(&a).unwrap_or_default()),
85	                );
86	            }
87	        }
88	        other => {
89	            out.insert(key.to_string(), other);
90	        }
91	    }
92	}
