95	
96	/// Curated extraction of the OSV v1.x fields that carry meaning across
97	/// sources, plus generic flattening of anything else. See the module docs
98	/// for why `database_specific` is absent.
99	fn normalize_osv(v: &Value) -> Map<String, Value> {
100	    let obj: Map<String, Value> = match v {
101	        Value::Object(m) => m.clone(),
102	        other => return flatten(other),
103	    };
104	    let mut out = Map::new();
105	
106	    // Direct scalars that exist in every OSV record class.
107	    for k in [
108	        "id",
109	        "modified",
110	        "published",
111	        "withdrawn",
112	        "summary",
113	        "details",
114	    ] {
115	        if let Some(s) = obj.get(k).and_then(Value::as_str) {
116	            if !s.is_empty() {
117	                out.insert(k.to_string(), Value::String(s.to_string()));
118	            }
119	        }
120	    }
121	
122	    // `aliases` / `related`: scalar string arrays — they survive flattening
123	    // as arrays, and identity unions on every element.
124	    for k in ["aliases", "related"] {
125	        if let Some(arr) = string_array(obj.get(k)) {
126	            if !arr.is_empty() {
127	                out.insert(k.to_string(), Value::Array(arr));
128	            }
129	        }
130	    }
131	
132	    // `severity`: [{type, score, source}] — first entry wins for the scalar,
133	    // all scores kept for evidence.
134	    if let Some(sev) = obj.get("severity").and_then(Value::as_array) {
135	        let scores: Vec<Value> = sev
136	            .iter()
137	            .filter_map(|s| s.get("score").and_then(Value::as_str))
138	            .map(|s| Value::String(s.to_string()))
139	            .collect();
140	        if let Some(first) = scores.first() {
141	            out.insert("severity".to_string(), first.clone());
142	        }
143	        if !scores.is_empty() {
144	            out.insert("severity_scores".to_string(), Value::Array(scores));
145	        }
146	    }
147	
148	    // `affected[]`: version knowledge. OSV packs multiple introduced/fixed
149	    // pairs into one SEMVER range (RustSec shape) while GHSA splits them
150	    // across entries; both land in the same flat lists here so the merge
151	    // unions intervals instead of comparing shapes.
152	    let mut ecosystems: Vec<Value> = Vec::new();
153	    let mut packages: Vec<Value> = Vec::new();
154	    let mut versions: Vec<Value> = Vec::new();
155	    let mut introduced: Vec<Value> = Vec::new();
156	    let mut fixed: Vec<Value> = Vec::new();
157	    let mut last_affected: Vec<Value> = Vec::new();
158	    for aff in obj
159	        .get("affected")
160	        .and_then(Value::as_array)
161	        .unwrap_or(&Vec::new())
162	    {
163	        if let Some(name) = aff
164	            .get("package")
165	            .and_then(|p| p.get("name"))
166	            .and_then(Value::as_str)
167	        {
168	            packages.push(Value::String(name.to_string()));
169	        }
170	        if let Some(eco) = aff
171	            .get("package")
172	            .and_then(|p| p.get("ecosystem"))
173	            .and_then(Value::as_str)
174	        {
175	            ecosystems.push(Value::String(eco.to_string()));
176	        }
177	        if let Some(vs) = string_array(aff.get("versions")) {
178	            versions.extend(vs);
179	        }
180	        for range in aff
181	            .get("ranges")
182	            .and_then(Value::as_array)
183	            .unwrap_or(&Vec::new())
184	        {
185	            for ev in range
186	                .get("events")
187	                .and_then(Value::as_array)
188	                .unwrap_or(&Vec::new())
189	            {
190	                for (key, sink) in [
191	                    ("introduced", &mut introduced),
192	                    ("fixed", &mut fixed),
193	                    ("last_affected", &mut last_affected),
194	                ] {
195	                    if let Some(s) = ev.get(key).and_then(Value::as_str) {
196	                        sink.push(Value::String(s.to_string()));
197	                    }
198	                }
199	            }
200	        }
201	    }
202	    dedup_into(&mut out, "ecosystems", ecosystems);
203	    dedup_into(&mut out, "packages", packages);
204	    dedup_into(&mut out, "affected_versions", versions);
205	    dedup_into(&mut out, "introduced_versions", introduced);
206	    dedup_into(&mut out, "fixed_versions", fixed);
207	    dedup_into(&mut out, "last_affected_versions", last_affected);
208	
209	    // `references[]`: {type, url} — flattened into parallel scalar arrays.
210	    let mut urls: Vec<Value> = Vec::new();
211	    let mut types: Vec<Value> = Vec::new();
212	    for r in obj
213	        .get("references")
214	        .and_then(Value::as_array)
215	        .unwrap_or(&Vec::new())
216	    {
217	        if let Some(u) = r.get("url").and_then(Value::as_str) {
218	            urls.push(Value::String(u.to_string()));
219	        }
220	        if let Some(t) = r.get("type").and_then(Value::as_str) {
221	            types.push(Value::String(t.to_string()));
222	        }
223	    }
224	    dedup_into(&mut out, "reference_urls", urls);
225	    dedup_into(&mut out, "reference_types", types);
226	
227	    // `ecosystem_specific`: the documented upstream extension point. RustSec
228	    // publishes affected FUNCTIONS here (`affects.functions` — canonical
229	    // paths keyed to version ranges), which no other source in the stack
230	    // carries; that is the one structured extraction worth doing.
231	    if let Some(eco) = obj.get("ecosystem_specific") {
232	        if let Some(functions) = eco
233	            .pointer("/affects/functions")
234	            .and_then(Value::as_object)
235	            .map(|m| m.keys().cloned().collect::<Vec<_>>())
236	        {
237	            if !functions.is_empty() {
238	                out.insert(
239	                    "affected_functions".to_string(),
240	                    Value::Array(functions.into_iter().map(Value::String).collect::<Vec<_>>()),
241	                );
242	            }
243	        }
244	        if let Some(info) = eco.get("informational").and_then(Value::as_str) {
245	            out.insert("informational".to_string(), Value::String(info.to_string()));
246	        }
247	    }
248	
249	    // Everything not already curated flows through the generic flattener so
250	    // unknown-but-real OSV fields survive into the pack (curated keys win on
251	    // collision — they are the ones with merge semantics).
252	    for (k, vv) in &obj {
253	        if matches!(k.as_str(), "database_specific") {
254	            continue;
255	        }
256	        if out.contains_key(k) {
257	            continue;
258	        }
259	        flatten_into(k, vv.clone(), 0, &mut out);
260	    }
261	    out
262	}
