264	// ── RustSec native advisory ─────────────────────────────────────────────────
265	
266	/// Split a RustSec advisory into (frontmatter TOML text, markdown body). The
267	/// file is one ```toml fenced block followed by prose; a file without the
268	/// fence yields no frontmatter and the whole text as body.
269	fn split_frontmatter(text: &str) -> (Option<&str>, &str) {
270	    let t = text.trim_start_matches('\u{feff}');
271	    let Some(after) = t.strip_prefix("```toml\n") else {
272	        return (None, t);
273	    };
274	    match after.find("\n```\n") {
275	        Some(i) => (Some(&after[..i]), &after[i + 5..]),
276	        // a fence that never closes: treat everything after the opener as
277	        // frontmatter-shaped text we cannot trust, keep it as body instead
278	        None => (None, t),
279	    }
280	}
281	
282	/// RustSec's native `crates/<crate>/RUSTSEC-*.md`: a ```toml frontmatter
283	/// (`[advisory]`/`[versions]`/`[affected]` tables) plus the advisory's
284	/// markdown prose. The `osv`-branch conversion drops `affected.functions`
285	/// and nulls `ecosystem_specific` (measured 2026-09-27: 0 of 1,252 records
286	/// carry functions there), so the native files are the ONLY source of the
287	/// curated vulnerable-function paths.
288	///
289	/// Facts both adapters carry land in the SAME key names (`id`, `aliases`,
290	/// `summary`, `severity`, `affected_functions`, `withdrawn`, …) so a recipe
291	/// can merge this source with an `osv` one without a bridge; RustSec-only
292	/// facts (`patched_versions`, `categories`, `keywords`, `date`) keep their
293	/// own names. Uncurated frontmatter keys flow through the generic
294	/// flattener prefixed by their table (`advisory_foo`), mirroring the osv
295	/// adapter's passthrough.
296	fn normalize_rustsec_md(text: &str) -> Map<String, Value> {
297	    let (fm, body) = split_frontmatter(text);
298	    let mut out = Map::new();
299	
300	    let parsed = fm
301	        .map(|f| f.parse::<toml::Value>())
302	        .transpose()
303	        .ok()
304	        .flatten();
305	    let tables: Option<&toml::value::Table> = match parsed.as_ref() {
306	        Some(toml::Value::Table(t)) => Some(t),
307	        _ => None,
308	    };
309	
310	    // Track what curated extraction consumed so the passthrough loop below
311	    // does not duplicate it under a prefixed name.
312	    let mut curated: Vec<(&str, &str)> = Vec::new();
313	    let sub = |name: &str| tables.and_then(|t| t.get(name)).and_then(|v| v.as_table());
314	    let advisory = sub("advisory");
315	    let versions = sub("versions");
316	    let affected = sub("affected");
317	    let put_str = |out: &mut Map<String, Value>, key: &str, s: String| {
318	        if !s.is_empty() {
319	            out.insert(key.to_string(), Value::String(s));
320	        }
321	    };
322	
323	    if let Some(advisory) = advisory {
324	        for k in ["id", "date", "url", "title", "withdrawn", "informational"] {
325	            if let Some(s) = advisory.get(k).and_then(|v| v.as_str()) {
326	                curated.push(("advisory", k));
327	                put_str(&mut out, k, s.to_string());
328	            }
329	        }
330	        // `cvss` is a bare vector string here; the osv adapter keeps the
331	        // first score in `severity` and all in `severity_scores` — same.
332	        if let Some(cvss) = advisory.get("cvss").and_then(|v| v.as_str()) {
333	            curated.push(("advisory", "cvss"));
334	            put_str(&mut out, "severity", cvss.to_string());
335	            out.insert(
336	                "severity_scores".to_string(),
337	                Value::Array(vec![Value::String(cvss.to_string())]),
338	            );
339	        }
340	        if let Some(pkg) = advisory.get("package").and_then(|v| v.as_str()) {
341	            curated.push(("advisory", "package"));
342	            out.insert(
343	                "packages".to_string(),
344	                Value::Array(vec![Value::String(pkg.to_string())]),
345	            );
346	        }
347	        for k in ["aliases", "related", "categories", "keywords"] {
348	            if let Some(arr) = advisory.get(k).and_then(|v| v.as_array()) {
349	                let vals: Vec<Value> = arr
350	                    .iter()
351	                    .filter_map(|v| v.as_str())
352	                    .map(|s| Value::String(s.to_string()))
353	                    .collect();
354	                if !vals.is_empty() {
355	                    curated.push(("advisory", k));
356	                    out.insert(k.to_string(), Value::Array(vals));
357	                }
358	            }
359	        }
360	    }
361	    if let Some(versions) = versions {
362	        for (src, dst) in [
363	            ("patched", "patched_versions"),
364	            ("unaffected", "unaffected_versions"),
365	        ] {
366	            if let Some(arr) = versions.get(src).and_then(|v| v.as_array()) {
367	                let vals: Vec<Value> = arr
368	                    .iter()
369	                    .filter_map(|v| v.as_str())
370	                    .map(|s| Value::String(s.to_string()))
371	                    .collect();
372	                if !vals.is_empty() {
373	                    curated.push(("versions", src));
374	                    out.insert(dst.to_string(), Value::Array(vals));
375	                }
376	            }
377	        }
378	    }
379	    if let Some(affected) = affected {
380	        // `functions` is an inline table of function path → version ranges;
381	        // the PATHS are the joinable fact (same key the osv adapter's
382	        // ecosystem_specific extraction produces). Sorted: the file's key
383	        // order must not reach the pack bytes.
384	        if let Some(fns) = affected.get("functions").and_then(|v| v.as_table()) {
385	            let mut paths: Vec<String> = fns.keys().cloned().collect();
386	            paths.sort();
387	            if !paths.is_empty() {
388	                curated.push(("affected", "functions"));
389	                out.insert(
390	                    "affected_functions".to_string(),
391	                    Value::Array(paths.into_iter().map(Value::String).collect()),
392	                );
393	            }
394	        }
395	    }
396	
397	    // Everything not curated flows through the generic flattener prefixed by
398	    // its table, so unknown-but-real frontmatter survives into the pack.
399	    if let Some(t) = tables {
400	        for (tname, table_val) in t {
401	            let Some(sub) = table_val.as_table() else {
402	                continue;
403	            };
404	            for (k, v) in sub {
405	                if curated.iter().any(|(tn, ck)| *tn == tname && ck == k) {
406	                    continue;
407	                }
408	                let toml_json =
409	                    |tv: &toml::Value| -> Value { serde_json::to_value(tv).unwrap_or(Value::Null) };
410	                flatten_into(&format!("{tname}_{k}"), toml_json(v), 0, &mut out);
411	            }
412	        }
413	    }
414	
415	    // The prose: first `# ` heading is the advisory's title when the
416	    // frontmatter did not carry one; the whole body is the `details`.
417	    let heading = body
418	        .lines()
419	        .find(|l| l.starts_with("# "))
420	        .map(|l| l[2..].trim().to_string());
421	    if let Some(h) = heading {
422	        put_str(&mut out, "summary", h);
423	    }
424	    let trimmed = body.trim();
425	    if !trimmed.is_empty() {
426	        put_str(&mut out, "details", trimmed.to_string());
427	    }
428	    out
429	}
430	
431	fn string_array(v: Option<&Value>) -> Option<Vec<Value>> {
432	    match v {
433	        Some(Value::Array(a)) if a.iter().all(|e| e.is_string()) => Some(a.to_vec()),
434	        Some(Value::String(s)) => Some(vec![Value::String(s.clone())]),
435	        _ => None,
436	    }
437	}
438	
439	fn dedup_into(out: &mut Map<String, Value>, key: &str, vals: Vec<Value>) {
440	    if vals.is_empty() {
441	        return;
442	    }
443	    let mut seen: Vec<String> = Vec::new();
444	    let mut kept: Vec<Value> = Vec::new();
445	    for v in vals {
446	        if let Some(s) = v.as_str() {
447	            if s.is_empty() || seen.iter().any(|x| x == s) {
448	                continue;
449	            }
450	            seen.push(s.to_string());
451	            kept.push(v);
452	        }
453	    }
454	    if !kept.is_empty() {
455	        out.insert(key.to_string(), Value::Array(kept));
456	    }
457	}
