220	/// Longest single path component we will create. 255 bytes is the limit on
221	/// ext4, APFS and NTFS alike; a longer component would fail at `create_dir`
222	/// halfway through a run instead of being reported up front.
223	const MAX_COMPONENT_BYTES: usize = 255;
224	
225	/// Basenames Windows cannot create, whatever the extension.
226	const WINDOWS_RESERVED: &[&str] = &[
227	    "con", "prn", "aux", "nul", "com1", "com2", "com3", "com4", "com5", "com6", "com7", "com8",
228	    "com9", "lpt1", "lpt2", "lpt3", "lpt4", "lpt5", "lpt6", "lpt7", "lpt8", "lpt9",
229	];
