231	/// Decide whether a prefix-stripped key can become a document.
232	///
233	/// An object key is an arbitrary UTF-8 string, not a path: `../../etc/passwd`,
234	/// `a//b`, `a\b`, a trailing dot and a 4 KB component are all legal keys. They
235	/// become a local path here, so each one is a decision rather than an accident:
236	///
237	/// - **`..`, `.`, an empty component, a leading `/`** — refused. A key that
238	///   escapes the mirror directory is the classic object-store traversal, and
239	///   `a//b` is a different key from `a/b` while being the same path.
240	/// - **A backslash** — refused. It is an ordinary character in a key and a
241	///   directory separator on Windows, so admitting it would index a different
242	///   set of documents per platform.
243	/// - **Control characters** — refused. They forge lines in the progress stream
244	///   (the #278 class) and are unrepresentable in half the tooling downstream.
245	/// - **A trailing `.` or space, or a Windows reserved basename** — refused
246	///   EVERYWHERE, not only on Windows, so one bucket produces one corpus
247	///   whatever machine indexes it. The report names the rule, so a refused key
248	///   is visible rather than silently missing.
249	/// - **A hidden (dot-prefixed) component** — skipped under
250	///   [`crate::ignore_rules::HIDDEN_RULE`], the same rule the walker applies at
251	///   depth > 0, and for the same reason: `.env`, `.git/config` and `.ssh/id_rsa`
252	///   live in buckets too, and "index this bucket" is not consent to publish
253	///   them into a queryable index. The two ignore FILES are the exception —
254	///   `.gitignore` and `.xerjignore` are fetched so the bucket's own ignore
255	///   rules still apply to it, and the walker then declines to index them
256	///   because of this same rule.
257	pub fn classify_key(rel: &str) -> KeyVerdict {
258	    if rel.is_empty() || rel.ends_with('/') {
259	        return KeyVerdict::Skip(rules::FOLDER_MARKER);
260	    }
261	    if rel.starts_with('/') || rel.contains('\\') {
262	        return KeyVerdict::Skip(rules::UNSAFE_KEY);
263	    }
264	    if rel.chars().any(|c| c.is_control()) {
265	        return KeyVerdict::Skip(rules::UNSAFE_KEY);
266	    }
267	    let components: Vec<&str> = rel.split('/').collect();
268	    let last = components.len() - 1;
269	    for (index, component) in components.iter().enumerate() {
270	        if component.is_empty() || *component == "." || *component == ".." {
271	            return KeyVerdict::Skip(rules::UNSAFE_KEY);
272	        }
273	        if component.len() > MAX_COMPONENT_BYTES {
274	            return KeyVerdict::Skip(rules::UNSAFE_KEY);
275	        }
276	        if component.ends_with('.') || component.ends_with(' ') || component.starts_with(' ') {
277	            return KeyVerdict::Skip(rules::UNSAFE_KEY);
278	        }
279	        let stem = component.split('.').next().unwrap_or(component);
280	        if WINDOWS_RESERVED
281	            .iter()
282	            .any(|reserved| stem.eq_ignore_ascii_case(reserved))
283	        {
284	            return KeyVerdict::Skip(rules::UNSAFE_KEY);
285	        }
286	        if component.starts_with('.') {
287	            let is_ignore_file = index == last
288	                && (*component == crate::ignore_rules::GITIGNORE
289	                    || *component == crate::ignore_rules::XERJIGNORE);
290	            if !is_ignore_file {
291	                return KeyVerdict::Skip(crate::ignore_rules::HIDDEN_RULE);
292	            }
293	        }
294	    }
295	    // The built-in build-output defaults, applied here as well as in the walk.
296	    // Same list, so the two can never drift; applying it early means a bucket
297	    // full of `node_modules/` costs no GET requests instead of costing them and
298	    // then being thrown away by the walker.
299	    if crate::ignore_rules::DEFAULT_IGNORE_PATTERNS
300	        .iter()
301	        .any(|pattern| {
302	            let dir = pattern.trim_end_matches('/');
303	            components[..last].contains(&dir)
304	        })
305	    {
306	        // Reported under the same label shape the walk uses for a pruned
307	        // directory, so `--dry-run` output reads the same for both sources.
308	        return KeyVerdict::Skip("default:build-output");
309	    }
310	    KeyVerdict::Admit
311	}
