423	    fn list(&self) -> Result<SourceListing> {
424	        let (files, report) =
425	            crate::walk::walk_reporting(&self.root, self.follow_symlinks, self.ignore)?;
426	        let seen = files.len() as u64 + report.files_skipped;
427	        let mut skipped = std::collections::BTreeMap::new();
428	        if report.files_skipped > 0 {
429	            skipped.insert("walk:ignored".to_string(), report.files_skipped);
430	        }
431	        Ok(SourceListing {
432	            entries: files
433	                .into_iter()
434	                .map(|f| SourceEntry {
435	                    rel: f.rel,
436	                    size: f.size,
437	                    change_token: None,
438	                    last_modified: None,
439	                })
440	                .collect(),
441	            skipped,
442	            seen,
443	        })
444	    }
