446	    fn open(&self, entry: &SourceEntry) -> Result<Box<dyn Read + Send>> {
447	        // `rel` came from this source's own walk, but it is still joined
448	        // defensively: a caller that round-trips entries through JSON could
449	        // hand back `../`, and a source must not read outside its root.
450	        match classify_key(&entry.rel) {
451	            KeyVerdict::Admit => {}
452	            KeyVerdict::Skip(rule) => {
453	                bail!("{} is not a readable relative path ({rule})", entry.rel)
454	            }
455	        }
456	        let path = self.root.join(&entry.rel);
457	        Ok(Box::new(std::fs::File::open(&path)?))
458	    }
459	
460	    fn ops(&self) -> SourceOps {
461	        SourceOps::default()
462	    }
463	}
