13	pub struct Inventory {
14	    pub files: Vec<FileEntry>,
15	    /// Durable document identity. New plans use the full-content key.
16	    pub keys: Vec<String>,
17	    /// Full digest used to detect mutations even when a legacy key is retained.
18	    pub digests: Vec<String>,
