22	/// Test-only witness: which pool the digest phase actually ran on. Phase A is
23	/// where `--workers` was silently disconnected (#240), and the pool a task
24	/// lands on is only observable from inside the task.
25	#[cfg(test)]
26	pub(crate) static OBSERVED_DIGEST_POOL_THREADS: std::sync::atomic::AtomicUsize =
27	    std::sync::atomic::AtomicUsize::new(0);
28	
29	/// Set when any digest ran on a thread that is not one of the scan pool's.
30	#[cfg(test)]
31	pub(crate) static DIGEST_RAN_OFF_THE_SCAN_POOL: std::sync::atomic::AtomicBool =
32	    std::sync::atomic::AtomicBool::new(false);
33	
34	/// Hash each file once, group equal digests, then byte-verify only digest peers.
35	///
36	/// This is linear in corpus bytes for adversarial common-prefix inputs rather
37	/// than pairwise O(n² × file_size).
38	///
39	/// `hashed` is called with each file's byte count as it completes.
40	/// Hashing reads the whole corpus, so on a large tree this is minutes of work
41	/// that reported nothing before #241. The callback runs on the scan pool's
42	/// workers and must therefore be `Sync`; it does no I/O of its own — it only
43	/// bumps the progress counters that the ticker thread reads.
44	pub fn resolve_reporting(
45	    files: Vec<FileEntry>,
46	    hashed: &(dyn Fn(u64) + Sync),
47	) -> Result<Inventory> {
48	    resolve_reporting_carried(files, &|_| None, &|_, _, _| {}, hashed)
49	}
50	
51	/// As [`resolve_reporting`], with a caller-supplied digest cache.
52	///
53	/// `carried` is asked, per file, for a digest the caller can PROVE is still the
54	/// digest of the current bytes; when it answers, the file is not read. Only
55	/// `--watch` answers it (see [`crate::watch`]), and only for files the OS told
56	/// it did not change since it hashed them in this same process — a metadata
57	/// shortcut on its own is explicitly not good enough for this decision, which is
58	/// why the plain route above hashes everything on every run.
59	///
60	/// `observed` is then called for every file with its final digest and whether
61	/// that digest came from a fresh read, which is how the watcher's cache gets
62	/// rebuilt after each pass. Both run on the scan pool's workers, hence `Sync`.
63	///
64	/// Safety of the shortcut, stated where it is implemented: a carried digest that
65	/// is WRONG cannot corrupt the index silently. The incremental projection in
66	/// [`crate::reconcile_plan`] compares the digest against the committed plan and
67	/// carries an assignment forward only on a match, so a stale carried digest
68	/// looks like "unchanged" — the failure mode is a missed update, not a bad
69	/// document — and the next event or fingerprint change repairs it.
70	pub fn resolve_reporting_carried(
71	    files: Vec<FileEntry>,
72	    carried: &(dyn Fn(&FileEntry) -> Option<String> + Sync),
73	    observed: &(dyn Fn(&FileEntry, &str, bool) + Sync),
74	    hashed: &(dyn Fn(u64) + Sync),
75	) -> Result<Inventory> {
76	    // Phase A belongs to the run's scan pool, not to rayon's global pool:
77	    // `--workers` has to bound the CPU-bound phase to mean anything (#240 §2).
78	    // The progress callback therefore fires from scan-pool threads — the ones
79	    // actually doing the hashing — rather than from rayon's global pool (#241).
80	    let digests: Vec<Result<String>> = crate::pool::install(|| {
81	        files
82	            .par_iter()
83	            .map(|file| {
84	                #[cfg(test)]
85	                {
86	                    OBSERVED_DIGEST_POOL_THREADS.fetch_max(
87	                        rayon::current_num_threads(),
88	                        std::sync::atomic::Ordering::Relaxed,
89	                    );
90	                    let on_scan_pool = std::thread::current()
91	                        .name()
92	                        .is_some_and(|n| n.starts_with("xerj-scan-"));
93	                    if !on_scan_pool {
94	                        DIGEST_RAN_OFF_THE_SCAN_POOL
95	                            .store(true, std::sync::atomic::Ordering::Relaxed);
96	                    }
97	                }
98	                let (digest, fresh) = match carried(file) {
99	                    // Cache hit: no read, and no byte credited to the hash
100	                    // phase either — the phase's totals were sized to the files
101	                    // this pass will actually read, so crediting a skipped file
102	                    // would push the percent past 100 and invent a rate.
103	                    Some(digest) => (Ok(digest), false),
104	                    None => {
105	                        let digest = full_digest(&file.path, file.size);
106	                        hashed(file.size);
107	                        (digest, true)
108	                    }
109	                };
110	                if let Ok(digest) = digest.as_ref() {
111	                    observed(file, digest, fresh);
112	                }
113	                digest
114	            })
115	            .collect()
116	    });
117	    let digests: Vec<String> = digests.into_iter().collect::<Result<_>>()?;
118	    resolve_with_digests(files, digests)
119	}
120	
121	fn resolve_with_digests(files: Vec<FileEntry>, digests: Vec<String>) -> Result<Inventory> {
122	    let mut groups: HashMap<&str, Vec<usize>> = HashMap::new();
123	    for (index, digest) in digests.iter().enumerate() {
124	        groups.entry(digest).or_default().push(index);
125	    }
126	
127	    let mut keep = vec![true; files.len()];
128	    let mut resolved_keys = digests.clone();
129	    let mut duplicates = Vec::new();
130	    for indices in groups.values() {
131	        if indices.len() < 2 {
132	            continue;
133	        }
134	        let mut indices = indices.clone();
135	        // Prefer a real in-tree path over a followed symlink as canonical.
136	        indices.sort_by_key(|&index| (files[index].is_symlink, files[index].rel.clone()));
137	        // A digest match is still only a candidate: verify exact bytes.
138	        let mut representatives: Vec<usize> = Vec::new();
139	        for index in indices {
140	            let canonical = representatives.iter().copied().find(|&candidate| {
141	                same_file_identity(&files[candidate].path, &files[index].path)
142	                    || files_equal(&files[candidate].path, &files[index].path).unwrap_or(false)
143	            });
144	            if let Some(canonical) = canonical {
145	                keep[index] = false;
146	                duplicates.push(DuplicateFile {
147	                    file_key: resolved_keys[canonical].clone(),
148	                    rel: files[index].rel.clone(),
149	                    path_id: files[index].rel_id.clone(),
150	                    is_symlink: Some(files[index].is_symlink),
151	                    duplicate_of: files[canonical].rel.clone(),
152	                    bytes: files[index].size,
153	                });
154	            } else {
155	                if !representatives.is_empty() {
156	                    // A full-digest collision was byte-proven, not assumed.
157	                    // Give the unequal representative a deterministic,
158	                    // path-specific discriminator so documents cannot collide.
159	                    resolved_keys[index] = format!(
160	                        "{}-collision-{:032x}",
161	                        digests[index],
162	                        xxhash_rust::xxh3::xxh3_128(files[index].rel_id.as_bytes())
163	                    );
164	                }
165	                representatives.push(index);
166	            }
167	        }
168	    }
169	
170	    let mut unique_files = Vec::new();
171	    let mut unique_keys = Vec::new();
172	    let mut unique_digests = Vec::new();
173	    for (index, file) in files.into_iter().enumerate() {
174	        if keep[index] {
175	            unique_files.push(file);
176	            unique_keys.push(resolved_keys[index].clone());
177	            unique_digests.push(digests[index].clone());
178	        }
179	    }
180	    duplicates.sort_by(|a, b| a.rel.cmp(&b.rel));
181	    Ok(Inventory {
182	        files: unique_files,
183	        keys: unique_keys,
184	        digests: unique_digests,
185	        duplicates,
186	    })
187	}
