189	pub fn verify(path: &Path, expected_size: u64, expected_digest: &str) -> Result<()> {
190	    let actual_size = std::fs::metadata(path)
191	        .with_context(|| format!("stat {}", path.display()))?
192	        .len();
193	    anyhow::ensure!(
194	        actual_size == expected_size,
195	        "{} changed size during autoindex (expected {}, now {}); retry the run",
196	        path.display(),
197	        expected_size,
198	        actual_size
199	    );
200	    let actual = full_digest(path, actual_size)?;
201	    anyhow::ensure!(
202	        actual == expected_digest,
203	        "{} changed content during autoindex; retry the run",
204	        path.display()
205	    );
206	    Ok(())
207	}
208	
209	fn full_digest(path: &Path, size: u64) -> Result<String> {
210	    let mut file =
211	        BufReader::new(File::open(path).with_context(|| format!("open {}", path.display()))?);
212	    let mut hash = Xxh3::new();
213	    let mut buf = [0u8; 64 * 1024];
214	    loop {
215	        let n = file.read(&mut buf)?;
216	        if n == 0 {
217	            break;
218	        }
219	        hash.update(&buf[..n]);
220	    }
221	    Ok(format!("axf2-{:032x}-{size:x}", hash.digest128()))
222	}
223	
224	fn files_equal(a: &Path, b: &Path) -> Result<bool> {
225	    let mut a = BufReader::new(File::open(a).with_context(|| format!("open {}", a.display()))?);
226	    let mut b = BufReader::new(File::open(b).with_context(|| format!("open {}", b.display()))?);
227	    let mut ab = [0u8; 64 * 1024];
228	    let mut bb = [0u8; 64 * 1024];
229	    loop {
230	        let an = read_chunk(&mut a, &mut ab)?;
231	        let bn = read_chunk(&mut b, &mut bb)?;
232	        if an != bn || ab[..an] != bb[..bn] {
233	            return Ok(false);
234	        }
235	        if an == 0 {
236	            return Ok(true);
237	        }
238	    }
239	}
