242	fn same_file_identity(a: &Path, b: &Path) -> bool {
243	    use std::os::unix::fs::MetadataExt;
244	    match (std::fs::metadata(a), std::fs::metadata(b)) {
245	        (Ok(a), Ok(b)) => a.dev() == b.dev() && a.ino() == b.ino(),
246	        _ => false,
247	    }
248	}
249	
250	#[cfg(not(unix))]
251	fn same_file_identity(_a: &Path, _b: &Path) -> bool {
252	    false
253	}
254	
255	fn read_chunk(reader: &mut impl Read, buf: &mut [u8]) -> std::io::Result<usize> {
256	    let mut read = 0;
257	    while read < buf.len() {
258	        let n = reader.read(&mut buf[read..])?;
259	        if n == 0 {
260	            break;
261	        }
262	        read += n;
263	    }
264	    Ok(read)
265	}
