37	/// Group envelopes into clusters. Deterministic: iteration follows the
38	/// envelope order, and cluster output order follows each cluster's minimum
39	/// member index.
40	pub fn cluster(envelopes: &[Map<String, Value>], identity: &Identity) -> Vec<Cluster> {
41	    // DSU over [0..envelopes) ∪ value nodes (mapped to >= envelopes). Value
42	    // nodes always lose unions (records have smaller indices), so every
43	    // root stays below envelopes.len().
44	    let mut parent: Vec<usize> = (0..envelopes.len()).collect();
45	    let mut value_nodes: HashMap<String, usize> = HashMap::new();
46	
47	    fn find(parent: &mut [usize], mut x: usize) -> usize {
48	        while parent[x] != x {
49	            parent[x] = parent[parent[x]]; // path halving
50	            x = parent[x];
51	        }
52	        x
53	    }
54	
55	    for (i, env) in envelopes.iter().enumerate() {
56	        for value in identity_values(env, &identity.edges) {
57	            let node = *value_nodes.entry(value).or_insert_with(|| {
58	                parent.push(parent.len());
59	                parent.len() - 1
60	            });
61	            let (ra, rb) = (find(&mut parent, i), find(&mut parent, node));
62	            if ra != rb {
63	                let (lo, hi) = if ra < rb { (ra, rb) } else { (rb, ra) };
64	                parent[hi] = lo;
65	            }
66	        }
67	    }
68	
69	    let mut by_root: Vec<Vec<usize>> = vec![Vec::new(); envelopes.len()];
70	    for i in 0..envelopes.len() {
71	        by_root[find(&mut parent, i)].push(i);
72	    }
73	    by_root
74	        .into_iter()
75	        .filter(|m| !m.is_empty())
76	        .map(|mut members| {
77	            members.sort_by_key(|&i| order_key(&envelopes[i], &identity.canonical_source_order));
78	            Cluster { members }
79	        })
80	        .collect()
81	}
