83	/// The identity-edge values of one envelope. `each = true` explodes string
84	/// arrays element-wise; a plain string field is one value; empty strings
85	/// and other types contribute nothing.
86	fn identity_values(env: &Map<String, Value>, edges: &[super::recipe::IdentityEdge]) -> Vec<String> {
87	    let mut out = Vec::new();
88	    for e in edges {
89	        match env.get(&e.field) {
90	            Some(Value::String(s)) if !s.is_empty() => out.push(s.clone()),
91	            Some(Value::Array(a)) if e.each => {
92	                for v in a {
93	                    if let Some(s) = v.as_str() {
94	                        if !s.is_empty() {
95	                            out.push(s.to_string());
96	                        }
97	                    }
98	                }
99	            }
100	            // each=false on an array: the array as a whole is not an
101	            // identity — arrays vary by source even for the same record.
102	            _ => {}
103	        }
104	    }
105	    out
106	}
