108	/// Sort key for members: the order list's rank first, then the envelope's
109	/// store key — stability that does not depend on directory iteration order.
110	fn order_key(env: &Map<String, Value>, order: &[String]) -> (usize, String) {
111	    let slug = env.get(SRC).and_then(Value::as_str).unwrap_or("");
112	    let key = env.get(KEY).and_then(Value::as_str).unwrap_or("");
113	    (slug_rank(order, slug), key.to_string())
114	}
