116	/// Which member "wins" a scalar: the first (by merge order) carrying a
117	/// non-empty value.
118	fn first_str<'a>(members: &[&'a Map<String, Value>], key: &str) -> Option<&'a str> {
119	    members
120	        .iter()
121	        .filter_map(|m| m.get(key).and_then(Value::as_str))
122	        .find(|s| !s.is_empty())
123	}
124	
125	/// Merge one passthrough key: an ARRAY in any member makes the result an
126	/// array (union across members, deduped, scalars folded in as elements —
127	/// sources disagree on cardinality more often than they agree); scalars
128	/// everywhere keep it a scalar, first non-empty under precedence.
129	fn merge_field(ranked: &[&Map<String, Value>], key: &str) -> Option<Value> {
130	    let any_array = ranked
131	        .iter()
132	        .any(|m| matches!(m.get(key), Some(Value::Array(_))));
133	    if any_array {
134	        return union_arrays(ranked, key).map(Value::Array);
135	    }
136	    if let Some(s) = first_str(ranked, key) {
137	        return Some(Value::String(s.to_string()));
138	    }
139	    ranked
140	        .iter()
141	        .find_map(|m| m.get(key).filter(|v| !v.is_null() && !v.is_string()))
142	        .cloned()
143	}
