145	/// Union arrays across members preserving member order, deduped. A lone
146	/// string folds in as a single element.
147	fn union_arrays(members: &[&Map<String, Value>], key: &str) -> Option<Vec<Value>> {
148	    let mut out: Vec<Value> = Vec::new();
149	    for m in members {
150	        match m.get(key) {
151	            Some(Value::Array(a)) => {
152	                for v in a {
153	                    if !out.contains(v) {
154	                        out.push(v.clone());
155	                    }
156	                }
157	            }
158	            Some(Value::String(s)) if !s.is_empty() => {
159	                let v = Value::String(s.clone());
160	                if !out.contains(&v) {
161	                    out.push(v);
162	                }
163	            }
164	            _ => {}
165	        }
166	    }
167	    (!out.is_empty()).then_some(out)
168	}
